\end{align}
where the last equality follows from $L^{-\nu/d}= 2^{\nu/d} (2L)^{-\nu/d}$ and $\ln L\le \ln 2L$.

Now consider the case $\omega\notin D_L$. By \eqref{eq:eiconv2},
\begin{align}
\mathbb Q(D_L^c)\le \mathbb Q(A^c_L)+\mathbb Q(B^c_L)+\mathbb Q(C^c_L).\label{eq:eiconv9}
\end{align}
Let $Z_\ell$ be a Bernoulli random variable such that $Z_\ell=1$ if $\theta^{(\ell)}$ is randomly drawn from a uniform distribution.
Then, by the Chernoff bounds \citep[see e.g.][p.48]{boucheron2013concentration},
\begin{align}
