\label{lem:star_ell}
Suppose Assumptions \ref{as:kernel}, \ref{as:smoothness}, and \ref{as:degeneracy} hold.	Let $\varepsilon_L$ be a positive sequence such that $\varepsilon_L\to 0$ and $r_L=o(\varepsilon_L)$.
Then, there exists a constant $M>0$ such that $\sup_{\omega\in D_L\cap E_{1L}}|p'\theta^*-p'\theta^{(\ell(\omega,L))}|/\varepsilon_{\ell(\omega,L)}\le M$  for all $L$ sufficiently large.

We show the result by contradiction.
Let $\{\omega_L\}\subset\Omega$  be a  sequence such that $\omega_L\in D_L\cap E_{1L}$ for all $L$.
First, assume that, for any $M>0$, there is a  subsequence  such that $|p'\theta^*-p'\theta^{(\ell(\omega_L,L))}|> M \varepsilon_{\ell(\omega_L,L)}$ for all $L$. This occurs if it contains a further subsequence along which, for all $L$, (i) $p'\theta^{(\ell(\omega_L,L))} - p'\theta^*>M\varepsilon_{\ell(\omega_L,L)}$ or (ii) $p'\theta^*-p'\theta^{(\ell(\omega_L,L))}>M\varepsilon_{\ell(\omega_L,L)}$.


\bigskip
\noindent
Case (i): $p'\theta^{(\ell(\omega_L,L))}-p'\theta^*>M\varepsilon_{\ell(\omega_L,L)}$ for all $L$ for some subsequence.

To simplify notation, we select a further subsequence $\{a_L\}$ of $\{L\}$  such that
for any $a_L<a_{L'}$, $\ell(\omega_{a_L},a_L)<\ell(\omega_{a_{L'}},a_{L'})$. This then  induces a sequence $\{\theta^{(\ell)}\}$ of expected improvement maximizers such that  $p'\theta^{(\ell)}-p'\theta^*>M\varepsilon_\ell$ for all $\ell,$ where each $\ell$ equals $\ell(\omega_{a_L},a_L)$ for some $a_L\in\mathbb N$. In what follows, we therefore omit the arguments of $\ell$, but this sequence's dependence on $(w_{a_L},a_L)$ should be implicitly understood.

Recall that $\mathcal{C}$ defined in equation \eqref{eq:calc} is a compact set and that $\Pi_{\mathcal C}\theta^{(\ell)}=\mathop{\rm arg\,min}_{\theta\in\mathcal C}\|\theta^{(\ell)}-\theta\|$ denotes the projection of $\theta^{(\ell)}$ on $\mathcal C$. 
Then
\begin{align}
 p'\theta^{(\ell)}-p'\theta^*&= (p'\theta^{(\ell)}-p'\Pi_{\mathcal C}\theta^{(\ell)})+(p'\Pi_{\mathcal C}\theta^{(\ell)}-p'\theta^*)\notag\\
&\le \|p\|\|\theta^{(\ell)}-\Pi_{\mathcal C}\theta^{(\ell)}\|+(p'\Pi_{\mathcal C}\theta^{(\ell)}-p'\theta^*)\le d(\theta^{(\ell)},\mathcal C)
,\label{eq:star_ell-1}
\end{align}
where the first inequality follows from the Cauchy-Schwarz inequality, and the second inequality follows from $p'\Pi_{\mathcal C}\theta^{(\ell)}-p'\theta^*\le 0$ due to $\Pi_{\mathcal C}\theta^{(\ell)} \in \mathcal C$.
Therefore, by equation \eqref{as:pm}, for any $M>0$
\begin{align}
\bar{g}(\theta^{(\ell)})-c(\theta^{(\ell)})_+\ge C_2d(\theta^{(\ell)},\mathcal C)> C_2M\varepsilon_\ell,\label{eq:star_ell0}
\end{align}
for all $\ell$ sufficiently large, where the last inequality follows from $p'\theta^{(\ell)}-p'\theta^*>M\varepsilon_\ell$. Take $M$ such that $C_2M>1$. Then $(\bar g(\theta^{(\ell)})-c(\theta^{(\ell)}))/\varepsilon_\ell>C_2M>1$ 
for all $\ell$ sufficiently large, contradicting $\omega_L\in E_{1L}$.

\bigskip
\noindent
Case (ii): Similar to Case (i), we work with a further subsequence along which $p'\theta^*-p'\theta^{(\ell)}>M\varepsilon_\ell$ for all $\ell$. Recall that along this subsequence, $\theta^{(\ell)} \notin \mathcal C$ because $0<\bar g(\theta^{(\ell)})-c(\theta^{(\ell)})\le \varepsilon_\ell$. We will construct $\tilde\theta^{(\ell)}\in\mathcal C^{-\varepsilon_\ell}$ s.t. $\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})>\mathbb{EI}_{\ell-1}(\theta^{(\ell)})$, contradicting the definition of $\theta^{(\ell)}$.

By Assumption \ref{as:degeneracy},
\begin{align}
d_H(\mathcal C^{-\varepsilon_\ell},\mathcal C)\le M \varepsilon_\ell,\label{eq:star_ell1}
\end{align}
for all $\ell$ such that $\varepsilon_\ell\le \tau_1$.
By the Cauchy-Schwarz inequality, for any $\tilde\theta$,
\begin{align}
p'\theta^*-p'\tilde\theta\le \|p\|\|\theta^*-\tilde\theta\|.\label{eq:star_ell2}
\end{align}
Therefore, minimizing both sides with respect to $\tilde \theta\in \mathcal C^{-\varepsilon_\ell}$ and noting that $\|p\|=1$, we obtain
\begin{align}
p'\theta^*-\sup_{\tilde\theta\in \mathcal C^{-\varepsilon_\ell}}p'\tilde\theta \le \inf_{\tilde\theta\in \mathcal C^{-\varepsilon_\ell}}\|\theta^*-\tilde\theta\|.\label{eq:star_ell3}
\end{align}
Further, noting that $\theta^*\in\mathcal C$,
\begin{align}
\inf_{\tilde\theta\in \mathcal C^{-\varepsilon_\ell}}\|\theta^*-\tilde\theta\|\le \sup_{\theta\in\mathcal C}\inf_{\tilde\theta\in \mathcal C^{-\varepsilon_\ell}}\|\theta-\tilde\theta\|\le d_H(\mathcal C^{-\varepsilon_\ell},\mathcal C).\label{eq:star_ell4}
\end{align}
By \eqref{eq:star_ell1}-\eqref{eq:star_ell4},
\begin{align}
p'\theta^*-\sup_{\theta\in \mathcal C^{-\varepsilon_\ell}} p'\theta \le M \varepsilon_\ell,\label{eq:star_ell5}
\end{align}
for all $\ell$ sufficiently large.
Therefore, for all $\ell$ sufficiently large, one has
\begin{align}
p'\theta^*-\sup_{\theta\in \mathcal C^{-\varepsilon_\ell}} p'\theta  <p'\theta^*-p'\theta^{(\ell)}, \label{eq:star_ell6}
\end{align}
implying existence of $\tilde \theta^{(\ell)}\in\mathcal C^{-\varepsilon_\ell}$ s.t.
\begin{align}
p'\tilde\theta^{(\ell)}>p'\theta^{(\ell)}.\label{eq:star_ell7}
\end{align}
By Lemma \ref{lem:bds}, for $t(\theta)\equiv (\bar g(\theta)-c(\theta))/s_\ell(\theta)$, one can write
\begin{align}
\mathbb{EI}_{\ell-1}(\theta^{(\ell)}) &\le (p'\theta^{(\ell)}-p'\theta^{*,\ell-1})_+\Bigl(1-\Phi\Bigl(\frac{t(\theta^{(\ell)})-R}{\varsigma}\Bigr)\Bigr)\\
&\le (p'\theta^{(\ell)}-p'\theta^{*,\ell-1})_+(1-\Phi(-R/\varsigma)), \label{eq:star_ell8}
\end{align}
where the last inequality uses $t(\theta^{(\ell)})>0$. Lemma \ref{lem:bds} also yields
\begin{align}
\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})&\ge (p'\tilde\theta^{(\ell)}-p'\theta^{*,\ell-1})_+\Bigl(1-\Phi\Bigl(\frac{t(\tilde \theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)\notag\\
&> (p'\theta^{(\ell)}-p'\theta^{*,\ell-1})_+\Bigl(1-\Phi\Bigl(\frac{t(\tilde \theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)\label{eq:star_ell9}
\end{align}
for all $\ell$ sufficiently large, where the second inequality follows from \eqref{eq:star_ell7}. Next, by Assumption \ref{as:degeneracy},
\begin{align}
t(\tilde \theta^{(\ell)})=\frac{\bar g(\tilde\theta^{(\ell)})-c(\tilde\theta^{(\ell)})}{s_\ell(\tilde\theta^{(\ell)})}\le \frac{-C_1\varepsilon_\ell}{s_\ell(\tilde\theta^{(\ell)})}\label{eq:star_ell10}
\end{align}
for all $\ell$ sufficiently large.
Note that  $s_\ell(\tilde\theta^{(\ell)})=O(r_\ell)$ by \eqref{eq:eiconv3a} and $r_\ell=o(\varepsilon_\ell)$ by assumption. Hence,  $t(\tilde \theta^{(\ell)})\to -\infty$.
This in turn implies
\begin{align}
\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})> (p'\theta^{(\ell)}-p'\theta^{*,\ell-1})_+(1-\Phi(-R/\varsigma))\label{eq:star_ell11}
\end{align}
for all $\ell$ sufficiently large. \eqref{eq:star_ell8} and \eqref{eq:star_ell11} jointly establish the desired contradiction.

\begin{align}
 p'\theta^{(\ell)}-p'\theta^*&= (p'\theta^{(\ell)}-p'\Pi_{\mathcal C}\theta^{(\ell)})+(p'\Pi_{\mathcal C}\theta^{(\ell)}-p'\theta^*)\notag\\
&\le \|p\|\|\theta^{(\ell)}-\Pi_{\mathcal C}\theta^{(\ell)}\|+(p'\Pi_{\mathcal C}\theta^{(\ell)}-p'\theta^*)\le d(\theta^{(\ell)},\mathcal C)
,\label{eq:star_ell-1}
\end{align}

\label{lem:star-current}
  Suppose Assumptions \ref{as:kernel}, \ref{as:smoothness}, and \ref{as:degeneracy} hold.	Let $\varepsilon_L$ be a positive sequence such that $\varepsilon_L\to 0$ and $r_L=o(\varepsilon_L)$.
  Then, there exists a constant $M>0$ such that $\sup_{\omega\in D_L\cap E_{1L}}|p'\theta^*-p'\theta^{*,\ell(\omega,L)}|/\varepsilon_{\ell(\omega,L)}\le M$ for all $L$ sufficiently large.

We show below $p'\theta^*-p'\theta^{*,\ell(\omega,L)-1}=O(\varepsilon_{\ell(\omega,L)})$ uniformly over $D_L\cap E_{1L}$ for some decreasing sequence $\varepsilon_\ell$ satisfying the assumptions of the lemma. The claim then follows by re-labeling $\varepsilon_\ell$.

Suppose by contradiction that, for any $M>0$, there is a  subsequence $\{\omega_{a_L}\}\subset \Omega$ along which $\omega_{a_L}\in D_{a_L}$ and $|p'\theta^*-p'\theta^{*,\ell(\omega_{a_L},a_L)-1}|>M\varepsilon_{\ell(\omega_{a_L},a_L)}$ for all $L$ sufficiently large. To simplify notation, we select a subsequence $\{a_L\}$ of $\{L\}$  such that
 for any $a_L<a_{L'}$, $\ell(\omega_{a_L},a_L)<\ell(\omega_{a_{L'}},a_{L'})$. This then  induces a sequence  such that    $|p'\theta^*-p'\theta^{*,\ell-1}|>M\varepsilon_\ell$ for all $\ell,$ where each $\ell$ equals $\ell(\omega_{a_L},a_L)$ for some $a_L\in\mathbb N$.
Similar to the proof of Lemma \ref{lem:star_ell}, we omit the arguments of $\ell$ below and construct a sequence of points $\tilde\theta^{(\ell)}\in\mathcal C^{-\varepsilon_{\ell}}$ such that $\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})>\mathbb{EI}_{\ell-1}(\theta^{(\ell)})$.

Arguing as in \eqref{eq:star_ell1}-\eqref{eq:star_ell4}, one may find a sequence of points $\tilde\theta^{(\ell)}\in \mathcal C^{-\varepsilon_\ell}$ such that
\begin{align}
p'\theta^*-p'\tilde\theta^{(\ell)}\le M_1 \varepsilon_\ell,\label{eq:star-current1}
\end{align}
for some $M_1>0$ and for all $\ell$ sufficiently large. Furthermore, by Lemma \ref{lem:star_ell},
\begin{align}
|p'\theta^*-p'\theta^{(\ell)}|\le M_2\varepsilon_\ell, \label{eq:star-current2}
\end{align}
for some $M_2>0$ and for all $\ell$ sufficiently large.
Arguing as in \eqref{eq:star_ell8},
\begin{align}
\mathbb{EI}_{\ell-1}(\theta^{(\ell)})&\le (p'\theta^{(\ell)}-p'\theta^{*,\ell-1})_+\bigl(1-\Phi(-R/\varsigma)\bigr)\notag\\
&= (p'\theta^*-p'\theta^{*,\ell-1}-(p'\theta^*-p'\theta^{(\ell)}))_+\bigl(1-\Phi(-R/\varsigma)\bigr)\notag\\
&\le (p'\theta^*-p'\theta^{*,\ell-1})\bigl(1-\Phi(-R/\varsigma)\bigr)+|p'\theta^*-p'\theta^{(\ell)}|,\label{eq:star-current3}
\end{align}
where the last inequality follows from the triangle inequality, $p'\theta^*-p'\theta^{*,\ell-1}\ge 0$, and $1-\Phi(\frac{-R}{\varsigma})\le 1.$
Similarly, by Lemma \ref{lem:bds},
\begin{align}
\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})&\ge (p'\tilde\theta^{(\ell)}-p'\theta^{*,\ell-1})_+\Bigl(1-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)\notag\\
&=(p'\theta^*-p'\theta^{*,\ell-1}-(p'\theta^*-p'\tilde\theta^{(\ell)}))_+\Bigl(1-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)\notag\\
&\ge (p'\theta^*-p'\theta^{*,\ell-1})\Bigl(1-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)-(p'\theta^*-p'\tilde\theta^{(\ell)}),\label{eq:star-current4}
\end{align}
where the last inequality holds for all $\ell$ sufficiently large because  $p'\theta^*-p'\tilde\theta^{(\ell)}\in(0, M_2\varepsilon_\ell]$ and one can find a subsequence $p'\theta^*-p'\theta^{*,\ell-1}>M_2\varepsilon_\ell$ so that $p'\theta^*-p'\theta^{*,\ell-1}-(p'\theta^*-p'\tilde\theta^{(\ell)})>0$ for all $\ell$ sufficiently large.


Subtracting \eqref{eq:star-current3} from \eqref{eq:star-current4} yields
\begin{align}
&~\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})-\mathbb{EI}_{\ell-1}(\theta^{(\ell)})\notag\\
\ge &~ (p'\theta^*-p'\theta^{*,\ell-1})\Bigl(\Phi\Bigl(\frac{-R}{\varsigma}\Bigr)-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)-(p'\theta^*-p'\tilde\theta^{(\ell)})-|p'\theta^*-p'\theta^{(\ell)}|\notag\\
\ge &~ (p'\theta^*-p'\theta^{*,\ell-1})\Bigl(\Phi\Bigl(\frac{-R}{\varsigma}\Bigr)-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)\Bigr)- (M_1+M_2) \varepsilon_\ell,\label{eq:star-current5}
\end{align}
where the last inequality follows from \eqref{eq:star-current1} and \eqref{eq:star-current2}.
Note that there is a constant $\zeta>0$ s.t.
\begin{align}
\Phi\Bigl(\frac{-R}{\varsigma}\Bigr)-\Phi\Bigl(\frac{t(\tilde\theta^{(\ell)})+R}{\varsigma}\Bigr)>\zeta,\label{eq:star-current6}
\end{align}
due to $t(\tilde\theta^{(\ell)})\to-\infty$ by \eqref{eq:star_ell10}, \eqref{eq:eiconv3a}, and $r_\ell=o(\varepsilon_\ell)$. Therefore, for all $\ell$ sufficiently large,
\begin{align}
\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})-\mathbb{EI}_{\ell-1}(\theta^{(\ell)})>M\zeta\varepsilon_\ell - (M_1+M_2)\varepsilon_\ell.\label{eq:star-current7}
\end{align}
One may take $M$ large enough so that, for some  positive constant $\gamma$, $M\zeta\varepsilon_\ell - (M_1+M_2)\varepsilon_\ell>\gamma\varepsilon_\ell$ for all $\ell$ sufficiently large, which implies $\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})-\mathbb{EI}_{\ell-1}(\theta^{(\ell)})>0$ for all $\ell$ sufficiently large. However, this contradicts the assumption that $\theta^{(\ell)}\notin\mathcal C^{-\varepsilon_\ell}$ is the expected improvement maximizer.

\label{lem:star-current_inner}
  Suppose Assumptions \ref{as:kernel}, \ref{as:smoothness}, and \ref{as:degeneracy} hold.	Let $\{\varepsilon_L\}$ be a positive sequence such that $\varepsilon_L\to 0$ and $r_L=o(\varepsilon_L)$.
  Then, there exists a constant $M>0$ such that $\sup_{\omega\in D_L\cap E_{2L}}|p'\theta^*-p'\theta^{*,\ell(\omega,L)}|/\varepsilon_{\ell(\omega,L)}\le M$   for all $L$ sufficiently large.

Note that, for any $L\in\mathbb N$, $\omega\in D_L\cap E_{2L}$, and $\ell=\ell(\omega,L)$, $\theta^{(\ell)}$ satisfies $\bar g(\theta^{(\ell)})-c(\theta^{(\ell)})\le 0$, hence $p'\theta^{^*,\ell}\ge p'\theta^{(\ell)}$, which in turn implies
\begin{align}
0\le p'\theta^*-p'\theta^{*,\ell}\le p'\theta^*-p'\theta^{(\ell)}.
\end{align}
Therefore, it suffices to show the existence of $M>0$ that ensures $(p'\theta^*-p'\theta^{(\ell(\omega,L))})_+\le M\varepsilon_{\ell(\omega,L)}$ uniformly over $D_L\cap E_{2L}$ for all $L$.
Suppose by contradiction that, for any $M>0$, there is a  subsequence $\{\omega_{a_L}\}\subset \Omega$ along which $\omega_{a_L}\in D_{a_L}\cap E_{2a_L}$ and $p'\theta^*-p'\theta^{(\ell(\omega_{a_L},a_L))}>M\varepsilon_{\ell(\omega_{a_L},a_L)}$ for all $L$ sufficiently large. Again, we select a subsequence $\{a_L\}$ of $\{L\}$  such that
for any $a_L<a_{L'}$, $\ell(\omega_{a_L},a_L)<\ell(\omega_{a_{L'}},a_{L'})$. This then  induces a sequence $\{\theta^{(\ell)}\}$ of expected improvement maximizers such that    $(p'\theta^*-p'\theta^{(\ell)})_+>M\varepsilon_\ell$ for all $\ell,$ where each $\ell$ equals $\ell(\omega_{a_L},a_L)$ for some $a_L\in\mathbb N$.

Similar to the proof of Lemma \ref{lem:star_ell}, we omit the arguments of $\ell$ below and prove the claim by contradiction.
Below, we assume that, for any $M>0$, there is a further subsequence along which $p'\theta^*-p'\theta^{(\ell)}>M\varepsilon_\ell$ for all $\ell$ sufficiently large.

Now let $\varepsilon_\ell'=\tilde C \varepsilon_\ell$ with $\tilde C>0$ specified below. By Assumption \ref{as:degeneracy}, for all $\tilde\theta\in\mathcal C^{-\varepsilon_\ell'}$, it holds that
\begin{align}
\bar g(\tilde\theta)-c(\tilde \theta)\le -\tilde C C_1 \varepsilon_\ell,
\end{align}
for all $\ell$ sufficiently large. Noting that $-\varepsilon_\ell\le \bar g(\theta^{(\ell)})-c(\theta^{(\ell)})$  and  taking $\tilde C$ such that $\tilde CC_1>1$, it follows that $\theta^{(\ell)}\notin \mathcal C^{-\varepsilon_\ell'}$ for all $\ell$ sufficiently large.

Arguing as in \eqref{eq:star_ell1}-\eqref{eq:star_ell4}, one may find a sequence of points $\tilde\theta^{(\ell)}\in \mathcal C^{-\varepsilon_\ell'}$ such that
\begin{align}
p'\theta^*-p'\tilde\theta^{(\ell)}\le M_1 \varepsilon'_\ell= M_1\tilde C\varepsilon_\ell,\label{eq:star-current_inner1}
\end{align}
This and the assumption that one can find a subsequence such that $p'\theta^*-p'\theta^{(\ell)}>M_1\tilde C\varepsilon_\ell$ for all $\ell$ imply
\begin{align}
p'\theta^*-p'\tilde\theta^{(\ell)}<p'\theta^*-p'\theta^{(\ell)},\label{eq:star_current_inner2}
\end{align}
for all $\ell$ sufficiently large. Now mimic the argument along \eqref{eq:star_ell8}-\eqref{eq:star_ell11} to deduce
\begin{align}
\mathbb{EI}_{\ell-1}(\tilde\theta^{(\ell)})>\mathbb{EI}_{\ell-1}(\theta^{(\ell)})
\end{align}
for all $\ell$ sufficiently large. However, this contradicts the assumption that $\theta^{(\ell)}\notin \mathcal C^{-\varepsilon_\ell'}$ is the expected improvement maximizer.

\label{lem:bds2}Suppose $\Theta\subset\mathbb R^d$ is bounded and $p\in \mathbb S^{d-1}$.
Suppose the evaluation points $(\theta^{(1)},\cdots,\theta^{(L)})$ are drawn by Algorithm \ref{alg:evalpts} and let Assumptions \ref{as:kernel} and \ref{as:smoothness}-(ii) hold.
For $\theta\in\Theta$ and $L\in\mathbb N$, let $\mathbb{I}_L(\theta)\equiv (p'\theta-p'\theta^{*,L})_+1\{\bar g(\theta)\le c(\theta)\}.$
Let $\{\varepsilon_L\}$ be a positive sequence such that $\varepsilon_L\to 0$ and $r_L=o(\varepsilon_L)$. Let $\eta_L\equiv\varepsilon_L/r_L.$
 Then, for any sequence $\{\theta_L\}\subset\Theta$ such that $|\bar g(\theta_L)-c(\theta_L)|>\varepsilon_L$,
\begin{align}
\mathbb{I}_L(\theta_L)-\gamma_L\le \mathbb{EI}_L(\theta_L)\le \mathbb{I}_L(\theta_L)+\gamma_L,\label{eq:lembds1}
\end{align}
 where $\gamma_L=O(\exp(-M\eta_L))$.

If $s_L(\theta_L)=0$, then the posterior variance of $c(\theta_L)$ is zero. Hence, $\mathbb{EI}_L(\theta_L)=\mathbb{I}_L(\theta_L)$, and the claim of the lemma holds.

Suppose $s_L(\theta_L)>0$. We first show the upper bound. Let $u\equiv (\bar g(\theta_L)-c_L(\theta_L))/s_L(\theta_L)$ and $t\equiv (\bar g(\theta_L)-c(\theta_L))/s_L(\theta_L)$.
By Lemma 6 in \citet{Bull_Convergence_2011}, we have $|u-t|\le R.$ Starting from Lemma \ref{lem:bds}(i), we can write
\begin{align}
	\mathbb{EI}_L(\theta_L)&\le (p'\theta_L-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t-R}{\varsigma}\Big)\Big)\notag\\
	&= (p'\theta_L-p'\theta^{*,L})_+(1\{\bar g(\theta_L)\le c(\theta_L)\}+1\{\bar g(\theta_L)> c(\theta_L)\})\Big(1-\Phi\Big(\frac{t-R}{\varsigma}\Big)\Big)\notag\\
	&\le \mathbb{I}_L(\theta_L)+(p'\theta_L-p'\theta^{*,L})_+1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{t-R}{\varsigma}\Big)\Big),\label{eq:bds1}
\end{align}
where the last inequality used $1-\Phi(x)\le 1$ for any $x\in\mathbb R$.
Note that one may write
\begin{align}
	1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{t-R}{\varsigma}\Big)\Big)&=1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)-s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big)\Big).\label{eq:bds2}
\end{align}
To be clear about the hyperparameter value at which  we evaluate $s_L$, we will write $s_L(\theta_L;\beta)$.
By the hypothesis that $\|c\|_{\mathcal H_{\bar\beta}}\le R$ and Lemma 4 in \citet{Bull_Convergence_2011}, we have
\begin{align}
\|c\|_{\mathcal H_{\beta_L}}\le R^2\prod_{k=1}^d(\overline{\beta}_k/\underline{\beta}_k) \equiv S.	\label{eq:eiconv3}
\end{align}
Note that there are $\lfloor\eta L\rfloor$ uniformly sampled points, and $K_\beta$ is associated with index $\nu\in (0,\infty)$.
As shown in the proof of Theorem 5 in \citet{Bull_Convergence_2011}, this ensures that
\begin{align}
	\sup_{\beta\in \prod_{k=1}^d[\underline\beta_k,\overline\beta_k]}s_L(\theta_L;\beta)=O(h_L^\nu(\ln L)^\chi)=O(r_L).\label{eq:eiconv3a}
\end{align}
Below, we simply write this result $s_L(\theta_L)=O(r_L).$
 This, together with $|\bar g(\theta_L)- c(\theta_L)|>\varepsilon_L$ and the fact that $1-\Phi(\cdot)$ is decreasing, yields
\begin{align}
1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)-s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big)\Big)&\le 1-\Phi\Big(\frac{\varepsilon_L}{ \varsigma s_L(\theta_L)}-\frac{R}{\varsigma}\Big)\notag\\
&\le 1-\Phi(M_1\eta_L-M_2),\label{eq:bds4z}
\end{align}
for some $M_1>0$ and where $M_2=R/\varsigma$.
Note that, by the triangle inequality,
\begin{align}
   1-\Phi(M_1\eta_L-M_2)\le  1-\Phi(M_1\eta_L)+| (1-\Phi(M_1\eta_L-M_2))- (1-\Phi(M_1\eta_L))|,\label{eq:bds4a}
\end{align}
and
\begin{align}
   1-\Phi(M_1\eta_L)\le \frac{1}{M_1\eta_L} \phi(M_1\eta_L)=O(\exp(-M\eta_L)),\label{eq:bds4}
\end{align}
for some $M>0$, 
where $\phi$ is the density of the standard normal distribution, and the  inequality follows from $1-\Phi(x)\le \phi(x)/x$. The second term on the right hand side of \eqref{eq:bds4a}
can be bounded as
\begin{align}
  | (1-\Phi(M_1\eta_L-M_2))- (1-\Phi(M_1\eta_L))|\le \phi(\tilde\eta_L)M_2=O(\exp(-M\eta_L))\label{eq:bds4b}
\end{align}
by the mean value theorem, where $\tilde\eta_L$ is a point between $M_1\eta_L$ and $M_1\eta_L-M_2$.
 The claim of the lemma then follows from  \eqref{eq:bds1}, \eqref{eq:bds4z}-\eqref{eq:bds4b}, and $(p'\theta_L-p'\theta_L^{*,L})$ being bounded because $\Theta$ is bounded.

 Similarly, for the lower bound, we have
 \begin{align}
 	\mathbb{EI}_L(\theta_L)&
 	\ge (p'\theta_L-p'\theta^*_L)_+\Big(1-\Phi\Big(\frac{t+R}{\varsigma}\Big)\Big)\notag\\
 	&\ge (p'\theta_L-p'\theta^*_L)_+1\{\bar g(\theta_L)\le c(\theta_L)\}\Big(1-\Phi\Big(\frac{t+R}{\varsigma}\Big)\Big)\notag\\
 	&\ge \mathbb{I}_L(\theta_L)-(p'\theta_L-p'\theta^*_L)_+1\{\bar g(\theta_L)\le c(\theta_L)\}\Phi\Big(\frac{t+R}{\varsigma}\Big).\label{eq:bds5}
 \end{align}
 Note that we may write
 \begin{align}
 	1\{\bar g(\theta_L)\le c(\theta_L)\}\Phi\Big(\frac{t+R}{\varsigma}\Big)=1\{\bar g(\theta_L)<  c(\theta_L)\}\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)+s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big),\label{eq:bds6}
 \end{align}
by $|\bar g(\theta_L)-c(\theta_L)|>\varepsilon_L$. Arguing as in \eqref{eq:bds5} and noting that $\Phi$ is increasing, one has
 \begin{align}
 1\{\bar g(\theta_L)<  c(\theta_L)\}\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)+s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big)&\le \Phi\Big(\frac{-\varepsilon_L}{\varsigma s_L(\theta_L)}+M_2\Big)\notag\\
 &\le \Phi(-M_1\eta_L+M_2),\label{eq:bds7}
 \end{align}
 for some $M_1>0$ and $M_2>0$. By the triangle inequality,
 \begin{align}
 	\Phi(-M_1\eta_L+M_2)\le \Phi(-M_1\eta_L) + |\Phi(-M_1\eta_L+M_2)-\Phi(-M_1\eta_L)|,\label{eq:bds8}
 \end{align}
 where arguing as in \eqref{eq:bds4},
 \begin{align}
 	\Phi(-M_1\eta_L) =1-\Phi(M_1\eta_L)=O(\exp(-M\eta_L)).\label{eq:bds9}
 \end{align}
 The second term on the right hand side of \eqref{eq:bds8}
 can be bounded as
 \begin{multline}
 	|\Phi(-M_1\eta_L+M_2)-\Phi(-M_1\eta_L)|\\
	=|(1-\Phi(M_1\eta_L-M_2))- (1-\Phi(M_1\eta_L))|\le \phi(\tilde\eta_L)M_2=O(\exp(-M\eta_L)),\label{eq:bds10}
 \end{multline}
 by the mean value theorem, where $\tilde\eta_L$ is a point between $M_1\eta_L$ and $M_1\eta_L-M_2$.
  The claim of the lemma then follows from  \eqref{eq:bds5}-\eqref{eq:bds10}, and $(p'\theta_L-p'\theta_L^{*,L})$ being bounded because $\Theta$ is bounded.

\begin{align}
	1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{t-R}{\varsigma}\Big)\Big)&=1\{\bar g(\theta_L)> c(\theta_L)\}\Big(1-\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)-s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big)\Big).\label{eq:bds2}
\end{align}

\begin{align}
 	1\{\bar g(\theta_L)\le c(\theta_L)\}\Phi\Big(\frac{t+R}{\varsigma}\Big)=1\{\bar g(\theta_L)<  c(\theta_L)\}\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)+s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big),\label{eq:bds6}
 \end{align}

\begin{align}
 1\{\bar g(\theta_L)<  c(\theta_L)\}\Phi\Big(\frac{\bar g(\theta_L)- c(\theta_L)+s_L(\theta_L)R}{\varsigma s_L(\theta_L)}\Big)&\le \Phi\Big(\frac{-\varepsilon_L}{\varsigma s_L(\theta_L)}+M_2\Big)\notag\\
 &\le \Phi(-M_1\eta_L+M_2),\label{eq:bds7}
 \end{align}

\label{lem:bds}Suppose $\Theta\subset\mathbb R^d$ is bounded and $p\in \mathbb S^{d-1}$  and let Assumptions \ref{as:kernel} and \ref{as:smoothness}-(ii) hold.
Let $t(\theta)\equiv (\bar g(\theta)-c(\theta))/s_L(\theta)$. For $\theta\in\Theta$ and $L\in\mathbb N$, let $\mathbb{I}_L(\theta)\equiv (p'\theta-p'\theta^{*,L})_+1\{\bar g(\theta)\le c(\theta)\}.$
 Then, (i) for any $L\in\mathbb N$ and $\theta\in\Theta$,
\begin{align}
(p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t(\theta)+R}{\varsigma}\Big)\Big)\le \mathbb{EI}_L(\theta)\le (p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t(\theta)-R}{\varsigma}\Big)\Big).
\end{align}
 Further, (ii) for any $L\in\mathbb N$ and $\theta\in\Theta$ such that $s_L(\theta)>0$,
\begin{align}
\mathbb{I}_L(\theta)	&\le \mathbb{EI}_L(\theta)\Big(1-\Phi\Big(\frac{R}{\varsigma}\Big)\Big)^{-1}.\label{eq:lembds2}
\end{align}

(i)	Let $u(\theta)\equiv (\bar g(\theta)-c_L(\theta))/s_L(\theta)$ and $t(\theta)\equiv (\bar g(\theta)-c(\theta))/s_L(\theta)$.
	By Lemma 6 in \citet{Bull_Convergence_2011}, we have $|u(\theta)-t(\theta)|\le R.$ Since $1-\Phi(\cdot)$ is decreasing, we have
	\begin{align}
		\mathbb{EI}_L(\theta)&=(p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{u(\theta)}{\varsigma }\Big)\Big)
		\le (p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t(\theta)-R}{\varsigma}\Big)\Big).
		\end{align}
Similarly,
\begin{align}
		\mathbb{EI}_L(\theta)&=(p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{u(\theta)}{\varsigma }\Big)\Big)
		\ge (p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t(\theta)+R}{\varsigma}\Big)\Big).
\end{align}

\noindent
(ii) For the lower bound in \eqref{eq:lembds2}, we have
\begin{align}
	\mathbb{EI}_L(\theta)&
	\ge (p'\theta-p'\theta^{*,L})_+\Big(1-\Phi\Big(\frac{t(\theta)+R}{\varsigma}\Big)\Big)\notag\\
	&\ge (p'\theta-p'\theta^{*,L})_+1\{\bar g(\theta)\le c(\theta)\}\Big(1-\Phi\Big(\frac{t(\theta)+R}{\varsigma}\Big)\Big)\notag\\
	&\ge \mathbb{I}_L(\theta)\bigl(1-\Phi(R/\varsigma)\bigr),
\end{align}
where the last inequality follows from $t(\theta)=(\bar g(\theta)-c(\theta))/s_L(\theta)\le 0$ and the fact that $1-\Phi(\cdot)$ is decreasing.

