 We establish each part of the theorem separately.

 \textbf{Part \ref{cor:eam_conv:c_hat_Lip}.}
Throughout, let $C>0$ denote a positive constant, which may be different in different appearances.
Define the event
\begin{multline}
E_n\equiv\big\{x^\infty\in\mathcal X^\infty:\|\hat D_n-D_{P}\|_{\infty}\le C \beta_n,~\sup_{\|\theta-\theta'\|\le \tau_n}\|\mathbb G_n(\theta)-\mathbb G_n(\theta'))\|\le (\ln n)^2\tau_n,\\
\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le C/\sqrt n,~\max_{j=1,\cdots,J}\sup_{\|\theta-\theta'\|<\tau_n}|\eta_{n,j}(\theta)-\eta_{n,j}(\theta')|\le C\tau_n\big\}.\label{eq:moll_lip1}
\end{multline}	
Note that $(\ln n)^2\tau_n/(-\tau_n\ln\tau_n)=(\ln n)^2/\zeta \ln n=\ln n/\zeta$, and hence tends to $\infty.$ By Assumption \ref{as:Lipschitz_m_over_sigma}-(i) and arguing as in the proof of Theorem 2 in  \citet{Andrews:1994aa}, condition  \eqref{eq:as_euclidean} in Lemma \ref{lem:se_rate} is satisfied with $v=d$. Also, by Lemma \ref{lem:correl_Lip}, \eqref{eq:correl_holder} in Lemma \ref{lem:se_rate} holds with $\gamma=1$. This therefore ensures the conditions of Lemma \ref{lem:se_rate}.

Similarly, by Assumption \ref{as:Lipschitz_m_over_sigma}-(i) $m^2_j(x,\theta)/\sigma_{P,j}^2(\theta)$ satisfies
\begin{align}
	\Big|\frac{m^2_j(x,\theta)}{\sigma_{P,j}^2(\theta)}-\frac{m^2_j(x,\theta)}{\sigma_{P,j}^2(\theta)}\Big|&\le \Big|\frac{m_j(x,\theta)}{\sigma_{P,j}(\theta)}+\frac{m_j(x,\theta')}{\sigma_{P,j}(\theta')}\Big|\Big|\frac{m_j(x,\theta)}{\sigma_{P,j}(\theta)}-\frac{m_j(x,\theta')}{\sigma_{P,j}(\theta')}\Big|\\
	&\le 2F(x)\bar M(x)\|\theta-\theta'\|.
\end{align}
Let $\bar F(x)\equiv 2F(x)\bar M(x)$.
By Theorem 2.7.11 in \citet{Vaart_Wellner2000aBK}, 
\begin{align}
 N_{[]}(\epsilon \|\bar F\|_{L^2_P},\mathcal M^2_{P},\|\cdot\|_{L^2_P})\le N(\epsilon,\Theta,\|\cdot\|)\le (\text{diam}(\Theta)/\epsilon)^d,
\end{align}
 where $N(\epsilon,\Theta,\|\cdot\|)$ is the covering number of $\Theta$. This ensures
\begin{align}
	\int_0^\infty \sup_{P\in\mathcal P}\sqrt{\ln N_{[]}(\epsilon \|\bar F\|_{L^2_P},\mathcal M^2_{P},\|\cdot\|_{L^2_P})}d\epsilon<\infty.
\end{align}
Further, for any $C>0$ 
\begin{align}
E_P[\bar F^2(X)1\{\bar F(X)>C\}]~\le~ E_P[\bar F^2(X)]P(\bar F(X)>C)	~\le~ 4E_P[|F(X)M(X)|^2]\frac{\|\bar F\|_{L^1_P}}{C}~\le~\frac{4M^2}{C},
\end{align}
which implies $\lim_{C\to\infty}\sup_{P\in\mathcal P}E_P[\bar F^2(X)1\{\bar F(X)>C\}]=0$. By Theorems 2.8.4 and 2.8.2 in \citet{Vaart_Wellner2000aBK}, this implies that $\mathcal S_P$ is Donsker and pre-Gaussian uniformly in $P\in\mathcal P.$ This therefore ensures the conditions of Lemma \ref{lem:eta_rate} (i). Note also that Assumption \ref{as:Lipschitz_m_over_sigma}-(i) ensures the conditions of Lemma \ref{lem:eta_rate} (ii).
Therefore, by Lemmas \ref{lem:se_rate}-\ref{lem:eta_rate} and Assumption \ref{as:momP_KMS}, for any $\eta>0$, there exists $C>0$ such that $\inf_{P\in\mathcal P}P(E_n)\ge1-\eta$ for all $n$ sufficiently large.

Let $\theta,\theta'\in \Theta$. For each $j$, we have
\begin{multline}
\left\vert\mathbb{G}_{n,j}^{b}(\theta )+\rho\hat{D}
_{n,j}(\theta)\lambda +\varphi_j(\hat{\xi}_{n,j}(\theta))-\mathbb{G}_{n,j}^{b}(\theta^\prime)-\rho\hat{D}
_{n,j}(\theta^\prime)\lambda -\varphi_j(\hat{\xi}_{n,j}(\theta^\prime))\right\vert \\\le 
|\mathbb{G}_{n,j}^{b}(\theta)-\mathbb{G}_{n,j}^{b}(\theta')|+\rho\|\hat D_{n,j}(\theta)-\hat D_{n,j}(\theta')\|\sup_{\lambda \in B^d}\|\lambda\|+|\varphi_j(\hat{\xi}_{n,j}(\theta))-\varphi_j(\hat{\xi}_{n,j}(\theta^\prime))|.\label{eq:moll_lip2}
\end{multline}
Assume that the sample path $\{X_i\}_{i=1}^\infty$ is such that the event $E_n$ holds. Conditional on $\{X_i\}_{i=1}^\infty$ and using $\mathbb{G}_{n,j}^{b}(\theta)-\mathfrak G^b_{n,j}(\theta)=\mathfrak G^b_{n,j}(\theta)\eta_{n,j}(\theta)$,
\begin{multline}
|\mathbb{G}_{n,j}^{b}(\theta)-\mathbb{G}_{n,j}^{b}(\theta')|\le |\mathfrak G^b_{n,j}(\theta)-\mathfrak G^b_{n,j}(\theta')|+2\sup_{\theta\in\Theta}|\mathfrak G^b_{n,j}(\theta)|\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\\
\le |\mathfrak G^b_{n,j}(\theta)-\mathfrak G^b_{n,j}(\theta')|+2\sup_{\theta\in\Theta}|\mathfrak G^b_{n,j}(\theta)|\frac{C}{\sqrt n}.\label{eq:moll_lip3}
\end{multline}

Define the event $F_n\in \mathcal C$ for the bootstrap weights by
\begin{align}
F_n\equiv\big\{m_n\in Q:\sup_{\|\theta-\theta'\|\le\tau_n}\|\mathfrak G^b_{n}(\theta)-\mathfrak G^b_{n}(\theta')\|\le (\ln n)^2\tau_n,~\sup_{\theta\in\Theta}\|\mathfrak G^b_{n}(\theta)\|\le C\big\}.\label{eq:moll_lip4}
\end{align}
By Lemma \ref{lem:se_rate} (ii) and the asymptotic tightness of $\mathfrak G^b_n$, for any $\eta>0$, there exists a $C$ such that $P^*_n(F_n)\ge 1-\eta$ for all $n$ sufficiently large.
Suppose that the multinomial bootstrap weight $M_n$ is such that
$F_n$ holds. Then, the right hand side of \eqref{eq:moll_lip3} is bounded by
$(\ln n)^2\tau_n+ C/\sqrt n$ for some $C>0$.

Next, by the triangle inequality and Assumption \ref{as:momP_KMS},
\begin{multline}
\|\hat D_{n,j}(\theta)-\hat D_{n,j}(\theta')\|\le \|\hat D_{n,j}(\theta)-D_{P,j}(\theta)\|+\|D_{P,j}(\theta)-D_{P,j}(\theta')\|+\|\hat D_{n,j}(\theta')-D_{P,j}(\theta')\|\\
\le C\beta_n + C\tau_n.\label{eq:moll_lip5}
\end{multline}

Finally, note that by the Lipschitzness of $\varphi_j$,  $|\varphi_j(\hat{\xi}_{n,j}(\theta))-\varphi_j(\hat{\xi}_{n,j}(\theta^\prime))|\le C|\hat{\xi}_{n,j}(\theta)-\hat{\xi}_{n,j}(\theta^\prime)|$ and
\begin{multline}
\hat{\xi}_{n,j}(\theta)-\hat{\xi}_{n,j}(\theta^\prime)
\\
= \kappa_n^{-1}\Big[\sqrt n\Big(\frac{\bar m_{n,j}(\theta)}{ \sigma_{P,j}(\theta)}(1+\eta_{n,j}(\theta))-\frac{E_P[m_j(X,\theta)]}{ \sigma_{P,j}(\theta)}\Big)-\sqrt n\Big(\frac{\bar m_{n,j}(\theta')}{ \sigma_{P,j}(\theta')}(1+\eta_{n,j}(\theta'))-\frac{E_P[m_j(X,\theta')]}{ \sigma_{P,j}(\theta')}\Big)\Big]\\
+\kappa_n^{-1}\sqrt n\Big(\frac{E_P[m_j(X,\theta)]}{ \sigma_{P,j}(\theta)}-\frac{E_P[m_j(X,\theta')]}{ \sigma_{P,j}(\theta')}\Big).\label{eq:moll_lip6}
\end{multline}
Hence,
\begin{multline}
|\hat{\xi}_{n,j}(\theta)-\hat{\xi}_{n,j}(\theta^\prime)|\le \kappa_n^{-1}|\mathbb G_{n,j}(\theta)-\mathbb G_{n,j}(\theta')|\\
+ \kappa_n^{-1}\sqrt n\Big|\frac{\bar m_{n,j}(\theta)}{ \sigma_{P,j}(\theta)}\eta_{n,j}(\theta)-\frac{\bar m_{n,j}(\theta')}{ \sigma_{P,j}(\theta')}\eta_{n,j}(\theta')\Big|+\kappa_n^{-1}\sqrt n D_{P,j}(\bar\theta)\|\theta-\theta'\|.\label{eq:moll_lip7}
\end{multline}
By Lemma \ref{lem:se_rate}, the right hand side of \eqref{eq:moll_lip7} can be further bounded by
\begin{multline}
\kappa_n^{-1}(\ln n)^2\tau_n+\kappa_n^{-1}\sqrt n\Big|\frac{\bar m_{n,j}(\theta)}{ \sigma_{P,j}(\theta)}-\frac{\bar m_{n,j}(\theta')}{ \sigma_{P,j}(\theta')}\Big||\eta_{n,j}(\theta)|\\
+\kappa_n^{-1}\sqrt n\Big|\frac{\bar m_{n,j}(\theta')}{ \sigma_{P,j}(\theta')}\Big||\eta_{n,j}(\theta)-\eta_{n,j}(\theta')|+C\kappa_n^{-1}\sqrt n\tau_n\\
\le \kappa_n^{-1}(\ln n)^2\tau_n+\kappa_n^{-1}\sqrt n\tau_n \frac{C}{\sqrt n}+C\kappa_n^{-1}\sqrt n\tau_n+C\kappa_n^{-1}\sqrt n\tau_n,\label{eq:moll_lip8}
\end{multline}
where the last inequality follows from Condition (i) and Lemma \ref{lem:eta_rate} (ii).


Combining \eqref{eq:moll_lip2}, \eqref{eq:moll_lip3}, \eqref{eq:moll_lip5}, and \eqref{eq:moll_lip6}-\eqref{eq:moll_lip8}, we obtain
\begin{align}
\left\vert\mathbb{G}_{n,j}^{b}(\theta )+\hat{D}
_{n,j}(\theta)\lambda +\varphi_j(\hat{\xi}_{n,j}(\theta))-\mathbb{G}_{n,j}^{b}(\theta^\prime)-\hat{D}
_{n,j}(\theta^\prime)\lambda -\varphi_j(\hat{\xi}_{n,j}(\theta^\prime))\right\vert\le C\varepsilon_n.
\end{align}
In particular, if $\mathbf{1}\left(\Lambda_n^b (\theta ,\rho ,\hat{c}_n(\theta))\cap \{p^{\prime }\lambda =0\}\neq \emptyset \right)=1$, it also holds that $\mathbf{1}\big(\Lambda_n^b (\theta^\prime ,\rho ,\hat{c}_n(\theta)+C\varepsilon_n)\cap\{p^{\prime }\lambda =0\}\neq \emptyset \big)=1$ because
\begin{align*}
\mathbb{G}_{n,j}^{b}(\theta^\prime)+\hat{D}
_{n,j}(\theta^\prime)\lambda +\varphi_j(\hat{\xi}_{n,j}(\theta^\prime)) \le \mathbb{G}_{n,j}^{b}(\theta )+\hat{D}
_{n,j}(\theta)\lambda +\varphi_j(\hat{\xi}_{n,j}(\theta))+C\varepsilon_n \le \hat{c}_n(\theta)+C\varepsilon_n,
\end{align*}
Recalling that $P^*_n(F_n)\ge 1-\eta$ for all $n$ sufficiently large, we then have
\begin{multline}
P^*_n\left(\big\{\Lambda_n^b (\theta' ,\rho ,\hat{c}_n(\theta)+C\varepsilon_n)\cap \{p^{\prime }\lambda =0\}\neq \emptyset\big\}\right)\\	
\ge P^*_n\left(\big\{\Lambda_n^b (\theta' ,\rho ,\hat{c}_n(\theta)+C\varepsilon_n)\cap \{p^{\prime }\lambda =0\}\neq \emptyset\big\}\cap F_n \right)	\\
\ge
P^*_n\left(\big\{\Lambda_n^b (\theta ,\rho ,\hat{c}_n(\theta))\cap \{p^{\prime }\lambda =0\}\neq \emptyset\big\} \cap F_n\right)\ge 1-\alpha-\eta.
\end{multline}
Since $\eta$ is arbitrary, we have
\begin{align*}
\hat c_n(\theta')\le \hat c_n(\theta)+C\varepsilon_n.
\end{align*}
Reversing the roles of $\theta$ and $\theta^\prime$ and noting that $\sup_{P\in\mathcal P}P(E_n)\to 0$  yields the first claim of the lemma.

 \textbf{Part \ref{cor:eam_conv:c_mollified_Lip}.}
To obtain the result in equation~\eqref{eq:c_mollified_Lip}, we use that for any $\theta,\theta^\prime \in \Theta$ such that $\|\theta-\theta'\|\le \tau_n$, $|\hat{c}_n(\theta)-\hat{c}_n(\theta^\prime)| \le C \varepsilon_n$ with probability approaching 1 uniformly in $P\in\mathcal P$ by the result in Part \ref{cor:eam_conv:c_hat_Lip}. This implies
\begin{multline*}
\vert\hat{c}_n(\theta)-\hat{c}_{n,\tau_n}(\theta)\vert=\left\vert \int_{\mathbb{R}^d} \hat{c}_n(\theta-\nu)\phi_{\tau_n}(\nu)d\nu - \hat{c}_n(\theta) \right\vert\le  \int_{\mathbb{R}^d}\left\vert \hat{c}_n(\theta-\nu)- \hat{c}_n(\theta) \right\vert \phi_{\tau_n}(\nu)d\nu \\
=\int_{\mathbb{B}_{\tau_n}}\left\vert \hat{c}_n(\theta-\nu)- \hat{c}_n(\theta) \right\vert \phi_{\tau_n}(\nu)d\nu\le C\varepsilon_n \int_{\mathbb{B}_{\tau_n}}\phi_{\tau_n}(\nu)d\nu \le C\varepsilon_n.
\end{multline*}


