	 	 \Longleftrightarrow &~ \begin{Bmatrix} \inf_{\lambda} p^\prime\lambda  &   \\ \text{s.t. } \lambda\in \frac{\sqrt n}{\rho }(\Theta-\theta_n), & \\ \{\mathbb G_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n})+\rho  D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n})\}(1+\eta_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n}))\le  \hat{c}_n(\theta_n+\frac{\lambda \rho }{\sqrt n}), \forall j  &  \end{Bmatrix} \leq 0  \notag\\
	 &\hspace{0.5in}\leq\begin{Bmatrix} \sup_{\lambda} p'\lambda  &   \\ \text{s.t. } \lambda\in \frac{\sqrt n}{\rho }(\Theta-\theta_n), & \\ \{\mathbb G_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n})+\rho  D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n}))\le  \hat{c}_n(\theta_n+\frac{\lambda \rho }{\sqrt n}), \forall j  &  \end{Bmatrix} \label{eq:cover_part1},
