\pi_{1,j}^*&= -\infty \Rightarrow \sqrt{n} \gamma_{1,P_n,j}(\theta_n) \to -\infty.\label{eq:pi_star_inf}
\end{align}
For any constraint $j$ for which $\pi_{1,j}^*= 0$, \eqref{eq:pi_star_zero} yields that replacing $\sqrt{n} \gamma_{1,P_n,j}(\theta_n)$ in \eqref{eq:cover_part2} with $\pi_{1,j}^*$ introduces a conservative distortion. Under Assumption \ref{as:correlation}-\ref{as:correlation_pair}, for any $j$ such that \eqref{eq:cond_both_CT_binding} holds, the substitutions in \eqref{eq:replace_CT_mix_LB} and \eqref{eq:replace_CT_mix_UB} yield $\tilde\mu_j\sqrt{n} \gamma_{1,P_n,j}(\theta_n)(1+\eta_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n}))-\tilde\mu_{j+R_1}\sqrt{n} \gamma_{1,P_n,j+R_1}(\theta_n)(1+\eta_{n,j+R_1}(\theta_n+\frac{\lambda \rho }{\sqrt n}))=0$, and therefore replacing this term with $\pi_{1,j}^*=0=\pi_{1,j+R_1}^*$ is inconsequential.

 For any $j$ for which $\pi_{1,j}^* = -\infty$, \eqref{eq:pi_star_inf} yields that for $n$ large enough, $\sqrt{n} \gamma_{1,P_n,j}(\theta_n)$ can be replaced with $\pi_{1,j}^*$. To see this, note that by the Cauchy-Schwarz inequality, Assumption \ref{as:momP_KMS} (i)-(ii), and $\lambda\in B^d_{n,\rho}$, it follows that 
\begin{align}
	\rho D_{P_{n},j}(\bar\theta_{n})\lambda \le \rho  \sqrt{d} (\|D_{P_{n},j}(\bar\theta_{n})-D_{P_{n},j}(\theta_{n})\|+\|D_{P_{n},j}(\theta_{n})\|)\le \rho \sqrt{d} (\rho  M/\sqrt n + \bar M),\label{eq:val6}
\end{align}
where $\bar{M}$ and $M$ are as defined in Assumption \ref{as:momP_KMS}-(i) and (ii) respectively, and we used that $\bar{\theta}_{n}$ lies component-wise between $\theta_{n}$ and $\theta_{n}+\frac{\lambda \rho }{\sqrt n}$. Using that $\mathbb{G}_{n,j}$ is asymptotically tight by Assumption \ref{as:bcs1}, we have that for any $\tau>0$, there exists a $T>0$ and $N_1\in\mathbb N$ such that for all $n\ge N_1$,
\begin{align}
&P_n \left(\max_{j:\pi^*_{1,j}=-\infty}\{\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})+\rho  D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}))\le  0 ,~\forall \lambda\in B^d_{n,\rho} \right)>1-\tau/2.\label{eq:pi_star_gamma_vanishes}
\end{align}
To see this, note that $\pi_{ij}^*=-\infty$ if and only if $\lim_{n \to \infty}\frac{\sqrt n}{\kappa_n}\gamma_{1P_nj}(\theta_n)=\pi_{1j}\in [-\infty,0)$. Suppose first that $\pi_{1j}>-\infty$. Then for all $\epsilon>0$ there exists $N_2 \in \mathbb{N}$ such that $
\Bigl\vert \frac{\sqrt n}{\kappa_n}\gamma_{1P_nj}(\theta_n)-\pi_{1j} \Bigr\vert \le \epsilon$, for all $n \ge N_2$. 
Choose $\epsilon>0$ such that $\pi_{1j}+\epsilon <0$. 

Let $N=\max\{N_1,N_2\}$. Then we have
\begin{align}
&~P_n \left(\max_{j:\pi^*_{1,j}=-\infty}\{\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})+\rho  D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}))\le  0 ,~\forall \lambda\in B^d_{n,\rho} \right)\notag\\
\ge &~P_n\left(\max_{j:\pi^*_{1,j}=-\infty} \{T+\rho  (\bar{M} + \tfrac{\rho  M}{\sqrt{n}})+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}))\le  0 \cap \max_{j:\pi^*_{1,j}=-\infty}\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}) \le T \right)\notag\\
\ge &~P_n\left(\max_{j:\pi^*_{1,j}=-\infty} \{T+\rho  (\bar{M} + \tfrac{\rho  M}{\sqrt{n}})+\kappa_n (\pi_{1j}+\epsilon)\}(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}))\le  0 \cap \max_{j:\pi^*_{1,j}=-\infty}\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}) \le T \right)\notag\\
= &~P_n\left(\max_{j:\pi^*_{1,j}=-\infty} \left\{\frac{T}{\kappa_n}+\frac{\rho }{\kappa_n} (\bar{M} + \tfrac{\rho  M}{\sqrt{n}})+(\pi_{1j}+\epsilon)\right\}(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}))\le  0 \cap \max_{j:\pi^*_{1,j}=-\infty}\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}) \le T \right)\notag\\
= 	&~P_n \left(\max_{j:\pi^*_{1,j}=-\infty}\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}) \le T\right)>1-\tau/2,~\forall n\ge N.\notag
\end{align}
If $\pi_{1j}=-\infty$ the same argument applies a fortiori.
