\label{lem:validity_ass_cont}
Suppose that Assumption \ref{as:momP_AS}, \ref{as:GMS}, \ref{as:momP_KMS} and \ref{as:bcs1} hold.
\begin{enumerate}[label=(\Roman*)]
\item \label{lem:validity_cont_ass} Let also Assumption \ref{ass:continuity_limit_cov} hold. Let $0<\alpha < 1/2$. Then,
\begin{align*}
\liminf_{n\to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}P(p'\theta\in CI_n)\ge 1-\alpha.
\end{align*}	
\item \label{lem:norho}
Let also Assumption \ref{ass:continuity_limit_cov_II} and either Assumption \ref{as:correlation} or \ref{ass:continuity_limit_cov} hold. Let $\hat{c}_n=\inf\{c\in\mathbb R_+:P^*(\{\Lambda_n^b (\theta ,+\infty ,c)\cap \{p^{\prime }\lambda =0\}\}\neq \emptyset)\ge 1-\alpha\}$, where $\Lambda_n^b$ is defined in equation \eqref{eq:Lambda_n} and $CI_n\equiv [-s(-p,\mathcal C_n(\hat{c}_n)),s(p,\mathcal C_n(\hat{c}_n))]$ with $s(q,\mathcal C_n(\hat{c}_n)),q\in \{p,-p\}$ defined in equation \eqref{eq:CI}. Then
\begin{align*}
\liminf_{n\to\infty}\inf_{P\in\mathcal P}\inf_{\theta\in\Theta_I(P)}P(p'\theta\in CI_n)\ge 1-\alpha.
\end{align*}
\end{enumerate}

 We establish each part of the Lemma separately.

 \textbf{Part \ref{lem:validity_cont_ass}.}
This part of the lemma replaces Assumptions \ref{as:correlation} with Assumption \ref{ass:continuity_limit_cov}. Hence we establish the result by showing that all claims that were made under Assumption \ref{as:correlation} remain valid under Assumption \ref{ass:continuity_limit_cov}. We proceed in steps.\smallskip

\noindent \underline{Step 1. Revisiting the proof of Lemma \ref{lem:empt}, equation \eqref{eq:Wdelta_lb_c}.}

Let $\mathcal{J}^*$ be as defined in \eqref{eq:Jstar}. If $\mathcal{J}^*=\emptyset$ we immediately have that Lemma \ref{lem:empt} continues to hold. Hence we assume that $\mathcal{J}^*\neq \emptyset$. To keep the notation simple, below we argue as if all $j=1,\dots,J$ belong to $\mathcal{J}^*$.

Consider the case that $c_{\pi^*}>0$. For some $c_{\pi^*}>\delta>0$, let
	\begin{align}
\mathfrak{W}(c-\delta)
\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda =0 &\cap \mathfrak{w}_{j}(\lambda)\le c-\delta , \: \forall j=1,\dots,J\big\}, \label{eq:Wdelta_ass_cont}
	\end{align}
	where we emphasize that the set $\mathfrak{W}(c-\delta)$ is obtained by a $\delta$-contraction of all constraints, including those indexed by $j=J_1+1,\dots,J$. By Assumption \ref{ass:continuity_limit_cov}, for any $\eta>0$ there exists a $\delta$ such that
	\begin{align*}
	\eta \ge \left\vert \mathrm{Pr}\left(\mathfrak{W}(c_{\pi^*})\neq \emptyset \right)-\mathrm{Pr}\left(\mathfrak{W}(c_{\pi^*}-\delta)\neq \emptyset \right)\right\vert = \mathrm{Pr}\left(\{\mathfrak{W}(c_{\pi^*})\neq \emptyset\} \cap  \{\mathfrak{W}(c_{\pi^*}-\delta)=\emptyset\}\right),\\
	\eta \ge \left\vert \mathrm{Pr}\left(\mathfrak{W}(c_{\pi^*}+\delta)\neq \emptyset \right)-\mathrm{Pr}\left(\mathfrak{W}(c_{\pi^*})\neq \emptyset \right)\right\vert = \mathrm{Pr}\left(\{\mathfrak{W}(c_{\pi^*}+\delta)\neq \emptyset\} \cap  \{\mathfrak{W}(c_{\pi^*})=\emptyset\}\right).
	\end{align*}
	The result follows.
















\smallskip

	\noindent \underline{Step 2. Revisiting the proof of Lemma \ref{lem:UnonEmpty}.}

	Case 1 of Lemma \ref{lem:UnonEmpty} is unaltered. Case 2 of Lemma \ref{lem:UnonEmpty} follows from the same argument as used in Case 1 of Lemma \ref{lem:UnonEmpty}, because under Assumption \ref{ass:continuity_limit_cov} as shown in step 1 of this proof all inequalities are tightened. In Case 3 of Lemma \ref{lem:UnonEmpty} the result in \eqref{eq:cover4} holds automatically by Assumption \ref{ass:continuity_limit_cov}-(ii). (As a remark, Lemmas \ref{lem:exist_sol}-\ref{lem:cbd} are no longer needed to establish Lemma \ref{lem:UnonEmpty}.)\smallskip

	\noindent \underline{Step 3. Revisiting the proof of Lemma \ref{lem:cv_convergence}.}
	Under Assumption \ref{ass:continuity_limit_cov} we do not need to merge paired inequalities. Hence, part (iii) of Lemma \ref{lem:cv_convergence} holds automatically because $\varphi^*_j(\xi) \le \varphi_j(\xi)$ for any $j$ and $\xi$. We are left to establish parts (i) and (ii) of Lemma \ref{lem:cv_convergence}. These follow immediately, because Lemma \ref{lem:empt} remains valid as shown in step 1 and by Assumption \ref{ass:continuity_limit_cov}, $\Pr(\mathfrak{W}(c)\neq \emptyset)$ is strictly increasing at $c=c_{\pi^*}$ if $c_{\pi^*}>0$. (As a remark, Lemma \ref{lem:pair} is no longer needed to establish Lemma \ref{lem:cv_convergence}.)\smallskip 

In summary, the desired result follows by applying Lemma \ref{lem:val} in the proof of Theorem \ref{thm:validity}-\ref{thm:validity:basic} as Lemmas \ref{lem:UnonEmpty}, \ref{lem:cv_convergence} and \ref{lem:empt} remain valid,  Lemmas \ref{lem:res}, \ref{lem:Jstar}, \ref{lem:eta_conv} and the Lemmas in Appendix \ref{app:asrep} are unaffected, and Lemmas \ref{lem:exist_sol}, \ref{lem:cbd}, \ref{lem:pair} are no longer needed.

\textbf{Part \ref{lem:norho}.} This is established by adapting the proof of Theorem \ref{thm:validity}-\ref{thm:validity:basic} as follows:

In the main proof, we pass to an a.s. representation early on, so that $\mathfrak{W}$ realizes jointly with other random variables (we denote almost sure representations adding a superscript ``$^*$" on the original variable). At the same time, we entirely drop $\rho$. This means that algebraic expressions, e.g. in the main proof, simplify as if $\rho=1$, but it also removes any constraints along the lines of $\lambda \in B^d_{n,\rho}$ in equation \eqref{eq:cover_part2}. Indeed, \eqref{eq:cover_part2} is replaced by: 
\begin{align*}
\dots \Leftarrow	 &\begin{Bmatrix} \inf_{\lambda} p^\prime\lambda     \\ \text{s.t. } \lambda\in \bar{\mathfrak{W}}^*(\bar{c}),  \\ \{\mathbb G^*_{n,j}(\theta_n+\lambda/\sqrt{n})+D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\lambda/\sqrt{n}))\le  \hat{c}_n(\theta_n+\lambda/\sqrt{n}), \forall j    \end{Bmatrix} \leq 0 \\
