Subsequent uses of $\rho$ in the main proof use that $\Vert \lambda \Vert \leq \sqrt{d}\rho=O_\mathcal{P}(1)$. For example, consider the argument following equation \eqref{eq:val6} or the argument just preceding equation \eqref{eq:cover4}, and so on. All these continue to go through because $\bar{\mathfrak{W}}^*(\bar{c})=O(1)$ by assumption.

Similar uses occur in Lemma \ref{lem:val}. The next major adaptation is that in \eqref{eq:set_W_Lpop_star} and \eqref{eq:val3}: we again drop $\rho$ but nominally introduce the constraint that $\lambda \in \bar{\mathfrak{W}}^*(\bar{c})$. However, for $c \leq \bar{c}$, this condition cannot constrain $\mathfrak{W}^*(c)$, and so we can as well drop it: The modified $\mathfrak{W}^*(c)$ equals $\bar{\mathfrak{W}}^*(c)$.

Next we argue that Lemma \ref{lem:exist_sol} continues to hold, now claimed for $\bar{\mathfrak{W}}^*$. To verify that this is the case, replace $B^d$ with $\bar{\mathfrak{W}}(\bar{c})$ throughout in Lemma \ref{lem:exist_sol}. This requires straightforward adaptation of algebra as $\bar{\mathfrak{W}}(\bar{c})$ is only stochastically and not deterministically bounded.

Finally, in Lemma \ref{lem:cv_convergence} we remove the $\rho$-constraint from $V_n^b$ and $V_n^I$ without replacement, and note that the lemma is now claimed for $\theta_n' \in \theta +\|\bar{\mathfrak{W}}(\bar c)\|_H /\sqrt{n} B^d$. Recall that in the lemma the a.s. representation of a set $A$ is denoted by $\tilde A$, and with some abuse of notation let the a.s. representation of $\bar{\mathfrak{W}}$ be denoted $\widetilde{ \bar{\mathfrak{W}}}$. Now we compare $\tilde V_n^b$ and $\tilde V_n^I$ with $\widetilde{ \bar{\mathfrak{W}}}$. To ensure that $\lambda$ is uniformly stochastically bounded in expressions like \eqref{eq:use-of-lambda}, we verify that the modified $\tilde V_n^b$ and $\tilde V_n^I$ inherit the property in Assumption \ref{ass:continuity_limit_cov_II}.
To see this, fix any unit vector $t \perp p$ and notice that any $t=\lambda /\| \lambda \|$ for $\lambda \in \widetilde{ \bar{\mathfrak{W}}}(c)$ or for $\lambda \in \tilde V_n^b(\theta_n',c)$ or for $\lambda \in \tilde V_n^I(\theta_n',c)$, $0<c\le \bar c$, satisfies this condition. By Assumption \ref{ass:continuity_limit_cov_II} and the Cauchy-Schwarz inequality, $\max_{\lambda \in \widetilde{ \bar{\mathfrak{W}}}(c)}t'\lambda=O(1)$ for any $c \le \bar{c}$. Since the value of this program is necessarily attained by a basic solution whose associated gradients span $t$, it must be the case that such solution is itself $O(1)$. 
Formally, let $C$ be the index set characterizing the solution, $\mathbb{Z}^C_i$ be the vector of realizations $\mathbb{Z}^j_i$ corresponding to $j \in C$, and $K^C(\theta_n')$ the matrix that stacks the corresponding gradients; then $(K^C(\theta_n'))^{-1}(\bar{c}\bm{1}-\mathbb{Z}^C_i)=O(1)$. By Lemma \ref{lem:exist_sol} and the fact that $\hat D_n(\theta_n')\stackrel{P}{\to} D$ by Assumption \ref{as:momP_KMS}, we then also have that $(\hat{K}^C(\theta_n'))^{-1}(\bar{c}\bm{1}-\mathbb{G}^b_{n,j})=O_\mathcal{P}(1)$, and so for $c \leq \bar{c}$, $V^b$ is bounded in this same direction. It follows that, by similar reasoning to the preceding paragraph, the comparison between $V_n^I(\theta_n',c)$ and $\bar{\mathfrak{W}}(c)$ in Lemma \ref{lem:cv_convergence} goes through.

\begin{align*}
\dots \Leftarrow	 &\begin{Bmatrix} \inf_{\lambda} p^\prime\lambda     \\ \text{s.t. } \lambda\in \bar{\mathfrak{W}}^*(\bar{c}),  \\ \{\mathbb G^*_{n,j}(\theta_n+\lambda/\sqrt{n})+D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\lambda/\sqrt{n}))\le  \hat{c}_n(\theta_n+\lambda/\sqrt{n}), \forall j    \end{Bmatrix} \leq 0 \\
	 &\hspace{0.5in}\leq\begin{Bmatrix} \sup_{\lambda} p'\lambda    \\ \text{s.t. } \lambda\in \bar{\mathfrak{W}}^*(\bar{c}),  \\ \{\mathbb G^*_{n,j}(\theta_n+\lambda/\sqrt{n})+ D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\}(1+\eta_{n,j}(\theta_n+\lambda/\sqrt{n}))\le  \hat{c}_n(\theta_n+\lambda/\sqrt{n}), \forall j    \end{Bmatrix},
	 \end{align*}

\begin{align}
& ~\exists \vartheta \in \Theta: p'\vartheta=p'\theta_n, \tfrac{\sqrt n \bar{m}_{n,j}(\vartheta)}{\hat\sigma_{n,j}(\vartheta)}\le  \hat{c}_n(\vartheta),  \forall j \\
\Longleftrightarrow &~\exists \lambda \in \tfrac{\sqrt n}{\rho }(\Theta-\theta_n): p'\lambda=0, \tfrac{\sqrt n \bar{m}_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n})}{\hat\sigma_{n,j}(\theta_n+\frac{\lambda \rho }{\sqrt n})}\le  \hat{c}_n(\theta_n+\tfrac{\lambda \rho }{\sqrt n}),  \forall j \\
\Longleftrightarrow &~\exists \lambda \in \tfrac{\sqrt n}{\rho }(\Theta-\theta_n): \\
 & ~ p'\lambda=0, \bigl(\mathbb G_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})+\rho  D_{P_n,j}(\bar\theta_n)\lambda+\sqrt{n} \gamma_{1,P_n,j}(\theta_n)\bigr)\bigl(1+\eta_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})\bigr)\le  \hat{c}_n(\theta_n+\tfrac{\lambda \rho }{\sqrt n}), \forall j \label{eq:coverage_ext}  
	 \end{align}

\begin{align}
\mu_j(\theta)\{ \mathbb{Z}_{j}+\rho D_{j}\lambda\} - \mu_{j+R_1}(\theta)\{\mathbb{Z}_{j+R_1}+\rho D_{j+R_1}\lambda\} &\le c,\label{eq:paired_bind_R4L}\\
-\mu_j(\theta)\{ \mathbb{Z}_{j}+\rho D_{j}\lambda\} + \mu_{j+R_1}(\theta)\{\mathbb{Z}_{j+R_1}+\rho D_{j+R_1}\lambda\} &\le c,\label{eq:paired_bind_R4U}	
\end{align}

\begin{align}

\mathfrak W(c)\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak w_{j}(\lambda)\le c, \: \forall j=1,\dots,J\big\} \label{eq:set_W_Lpop}.
\end{align}

\begin{align}
\mathfrak W^{\delta}(c)
\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda =0 &\cap \mathfrak w_{j}(\lambda)\le c+\delta , \: \forall j=1,\dots,J_1, \notag\\
&\cap \mathfrak w_{j}(\lambda)\le c , \: \forall j=J_1+1,\dots,J\big\}. \label{eq:Wdelta}
	\end{align}

\label{lem:val}
Let Assumptions \ref{as:momP_AS}, \ref{as:GMS}, \ref{as:correlation}, \ref{as:momP_KMS}, and \ref{as:bcs1} hold. Let $\{P_n,\theta_n\}$ be a sequence such that $P_n\in\mathcal P$ and $\theta_n \in \Theta_I(P_n)$ for all $n$ and $\kappa_n^{-1}\sqrt{n}\gamma_{1,P_n,j}(\theta_n) \to \pi_{1j} \in \mathbb{R}_{[-\infty]},~j=1,\dots,J,$
$\Omega_{P_n} \stackrel{u}{\rightarrow} \Omega,$ and
$D_{P_n}(\theta_n) \to D$.
Then,
\begin{align}
\liminf_{n \to \infty} P_n\left( U_n(\theta_n,\hat{c}_{n,\rho})\neq \emptyset \right) \ge 1-\alpha.
\label{eq:validity}
\end{align}

We consider a subsequence along which $ \liminf_{n\to\infty}P_n(U_{n}(\theta_{n},\hat{c}_{n,\rho}\ne\emptyset)$ is achieved as a limit. For notational simplicity, we use $\{n\}$ for this subsequence below.

Below, we construct a sequence of critical values  such that
\begin{align}
	\hat c_n(\theta_n')\ge c^{I}_n(\theta_n')+ o_{P_n}(1),\label{eq:chat_cI}
\end{align} 
and $c^{I}_n(\theta_n')\stackrel{P_n}{\to} c_{\pi^*}$ for any $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$. The construction is as follows. When $c_{\pi^*}=0$, let $c^{I}_n(\theta_n')=0$ for all $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$, and hence $c^{I}_n(\theta_n')\stackrel{P_n}{\to} c_{\pi^*}$. If $c_{\pi^*}>0$, let $c^I_n(\theta_n)\equiv \inf\{c\in\mathbb{R}_+:P^*_n(V^I_n(\theta_n,c))\ge 1-\alpha\}$, where $V^I_n$ is defined as in Lemma \ref{lem:cv_convergence}. By Lemma \ref{lem:cv_convergence} (iii), this critical value sequence satisfies \eqref{eq:chat_cI} with probability approaching 1.
Further, by Lemma \ref{lem:cv_convergence} (ii), $c^{I}_n(\theta_n')\stackrel{P_n}{\to} c_{\pi^*}$ for any $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$.

For each $\theta\in\Theta$,  let
\begin{align}
	c^{I}_{n,\rho}(\theta)\equiv\inf_{\lambda\in B^d_{n,\rho}}c^I_n(\theta+\tfrac{\lambda \rho }{\sqrt n}).
\end{align}
Since the $o_{P_n}(1)$ term in \eqref{eq:chat_cI} does not affect the argument below, we redefine $c^{I}_{n,\rho}(\theta_n)$ as $c^{I}_{n,\rho}(\theta_n)+o_{P_n}(1)$.
By \eqref{eq:chat_cI} and simple addition and subtraction,
\begin{align}
P_{n}\Big(U_{n}(\theta_{n},\hat{c}_{n,\rho}(\theta_{n}))\neq \emptyset\Big) &
\ge P_{n}\Big(U_{n}(\theta_{n},c^{I}_{n,\rho}(\theta_{n}))\neq \emptyset\Big)\notag\\
&=\Pr(\mathfrak{W}(c_{\pi^*})\ne\emptyset)+\Big[ P_n\Big(U_{n}(\theta_{n},c^{I}_{n,\rho}(\theta_{n}))\ne\emptyset\Big)-	\Pr\Big(\mathfrak{W}(c_{\pi^*})\ne\emptyset\Big)\Big].\label{eq:val_3_1}
\end{align}
As previously argued, $\mathbb G_{n}(\theta_n+\frac{\lambda \rho }{\sqrt n})\stackrel{d}{\to} \mathbb{Z}$. Moreover, by Lemma~\ref{lem:eta_conv}, 
$\sup_{\theta\in\Theta}\|\eta_{n}(\theta)\|\stackrel{p}{\to} 0$ uniformly in $\mathcal{P}$, and by Lemma \ref{lem:cv_convergence}, $c^I_{n,\rho}(\theta_n)\stackrel{p}{\to}c_{\pi^*}$.
 Therefore, uniformly in $\lambda\in B^d$, the sequence $\{(\mathbb G_{n}(\theta_n+\frac{\lambda \rho }{\sqrt n}),\eta_{n}(\theta_{n}+\frac{\lambda \rho }{\sqrt n}),c^{I}_{n,\rho}(\theta_n))\}$ satisfies 
\begin{align}
	\bigl(\mathbb G_{n}(\theta_n+\tfrac{\lambda \rho }{\sqrt n}),	\eta_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n}),c_{n,\rho}^{I}(\theta_n)\bigr)\stackrel{d}{\to} (\mathbb{Z},0,c_{\pi^*}).
\end{align}
In what follows, using Lemma 1.10.4 in \citet{Vaart_Wellner2000aBK} we take $(\mathbb{G}^*_{n}(\theta_n+\frac{\lambda \rho }{\sqrt n}),\eta^*_{n}, c^*_{n})$ to be the almost sure representation of $(\mathbb G_{n}(\theta_n+\frac{\lambda \rho }{\sqrt n}),\eta_{n}(\theta_{n}+\frac{\lambda \rho }{\sqrt n}),c_{n,\rho}^{I}(\theta_n))$ defined on some probability space $(\Omega,\mathcal F,\mathbf P)$ such that
 $(\mathbb G^*_{n}(\theta_n+\frac{\lambda \rho }{\sqrt n}),\eta^*_{n}, c^*_{n})\stackrel{a.s.}{\to}(\mathbb{Z}^*,0, c_{\pi^*})$, where $\mathbb{Z}^*\stackrel{d}{=}\mathbb{Z}$. 


For each $\lambda\in\mathbb{R}^d$, we define analogs to the quantities in \eqref{eq:uj} and \eqref{eq:wj} as
\begin{align}
u^*_{n,j,\theta_n}(\lambda)&\equiv	\bigl\{\mathbb G^*_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})+\rho D_{P_{n},j}(\bar\theta_n)\lambda+\pi^*_{1,j}\bigr\}(1+\eta^*_{n,j}),\label{eq:ujstar}\\
\mathfrak{w}^*_{j}(\lambda)&\equiv \mathbb{Z}^*_{j}+\rho D_{j}\lambda+\pi^*_{1,j}.\label{eq:wjstar}
\end{align}
 where we used that by Lemma \ref{lem:Jstar}, $\kappa_n^{-1}\sqrt{n} \gamma_{1,P,j}(\theta_n)-\kappa_n^{-1}\sqrt{n} \gamma_{1,P,j}(\theta_n^\prime)=o(1)$ uniformly over $\theta_n^\prime \in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ and therefore $\pi_{1,j}^*$ is constant over this neighborhood, and we applied a similar replacement as described in equations \eqref{eq:paired_bind_R2L}-\eqref{eq:paired_bind_R4U} for the case that $\pi_{1,j}^*=0=\pi_{1,j+R_1}^*$.
Similarly, we define analogs to the sets in \eqref{eq:set_U_NL} and \eqref{eq:set_W_Lpop} as
\begin{align}
U^*_{n}(\theta_{n},c_{n}^{*})&\equiv	\big\{\lambda\in B^d_{n,\rho}: p^\prime \lambda = 0 \cap u^*_{n,j,\theta_n}(\lambda)\le c_{n}^{*}, \: \forall j=1,\dots,J\big\}, \label{eq:set_U_NL_star}\\
\mathfrak W^*(c_{\pi^*})&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak{w}^*_{j}(\lambda)\le c_{\pi^*},~\forall j=1,\dots,J\big\}.\label{eq:set_W_Lpop_star}
\end{align}
 It then follows that equation (\ref{eq:val_3_1}) can be rewritten as
\begin{align}
P_{n}\Big(U_{n}(\theta_{n},\hat{c}_{n,\rho}(\theta_{n}))\neq \emptyset\Big)\ge \mathbf P(\mathfrak{W}^*(c_{\pi^*})\ne\emptyset)+\Big[ \mathbf P\Big(U^*_{n}(\theta_{n},c^*_n)\ne\emptyset\Big)-	\mathbf P\Big(\mathfrak{W}^*(c_{\pi^*})\ne\emptyset\Big)\Big].\label{eq:val3}
\end{align} 
By the definition of $c_{\pi^*}$, we have $\mathbf P(\mathfrak{W}^*(c_{\pi^*})\ne\emptyset)\ge 1-\alpha$. Therefore, we are left to show that the second term on the right hand side of \eqref{eq:val3} tends to 0 as $n\to\infty$.

 Define 
 \begin{equation}
 \label{eq:Jstar}
\mathcal J^*\equiv\{j=1,\cdots,J:\pi^*_{1,j}=0\} .
 \end{equation}
\noindent \textbf{Case 1.} Suppose first that $\mathcal J^*= \emptyset$, which implies $J_2=0$ and $\pi^*_{1,j}=-\infty$ for all $j.$
Then we have
\begin{align}
U^*_{n}(\theta_{n},c^{*}_{n})=\{\lambda \in  B^d_{n,\rho}:p^\prime\lambda =0\},~~~	\mathfrak{W}^*(c_{\pi^*})=\{\lambda \in  \mathfrak B^d_\rho:p^\prime\lambda =0\},
\end{align}
with probability 1, and hence 
\begin{align}
	\mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})\neq \emptyset \} \cap \{ \mathfrak{W}^*(c_{\pi^*})\neq \emptyset\}  \Big)=1.\label{eq:val9}
\end{align}
This in turn implies that
\begin{align}
 \Big| \mathbf{P}\Big(U^*_{n}(\theta_{n},c^{*}_{n})\neq \emptyset \} \Big)
- \mathbf{P}\Big(\mathfrak{W}^*(c_{\pi^*})\neq \emptyset\} \Big)\Big|=0,\label{eq:val10}
\end{align}
where we used $|\mathbf P(A)-\mathbf P(B)|\le \mathbf P(A\Delta B)\le 1-\mathbf P(A\cap B)$ for any pair of events $A$ and $B.$ Hence, the term in the square brackets in \eqref{eq:val3} is 0.

\noindent \textbf{Case 2.} Now consider the case that $\mathcal{J}^*\neq \emptyset$. We show that the term in  the square brackets in \eqref{eq:val3} converges to 0.
To that end, note that for any events $A,B$,
\begin{align}
\Big\vert\mathbf{P}(A\neq \emptyset) - \mathbf{P}(B\neq \emptyset)  \Big\vert
\le \Big\vert &\mathbf{P}(\{A= \emptyset \} \cap \{ B \neq \emptyset\})+
\mathbf{P}(\{A\neq \emptyset \} \cap \{ B =\emptyset\})\Big\vert \label{eq:cover5}
\end{align}
Hence, we aim to establish that for $A=U^*_{n}(\theta_{n},c^{*}_{n})$, $B= \mathfrak{W}^*(c_{\pi^*})$, the right hand side of equation (\ref{eq:cover5}) converges to zero. But this is guaranteed by Lemma \ref{lem:UnonEmpty}. 
Therefore, the conclusion of the lemma follows.

\begin{align}
U^*_{n}(\theta_{n},c_{n}^{*})&\equiv	\big\{\lambda\in B^d_{n,\rho}: p^\prime \lambda = 0 \cap u^*_{n,j,\theta_n}(\lambda)\le c_{n}^{*}, \: \forall j=1,\dots,J\big\}, \label{eq:set_U_NL_star}\\
\mathfrak W^*(c_{\pi^*})&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak{w}^*_{j}(\lambda)\le c_{\pi^*},~\forall j=1,\dots,J\big\}.\label{eq:set_W_Lpop_star}
\end{align}

\label{lem:UnonEmpty}
Let Assumptions \ref{as:momP_AS}, \ref{as:GMS}, \ref{as:correlation}, \ref{as:momP_KMS}, and \ref{as:bcs1} hold. Let $(P_n,\theta_n)$ have the almost sure representations given in Lemma \ref{lem:val}, and let $\mathcal J^*$ be defined as in \eqref{eq:Jstar}. Assume that $\mathcal J^* \neq \emptyset$.
Then for any $\eta>0$, there exists  $N \in \mathbb{N}$ such that 
\begin{align}
&\mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})\neq\emptyset \} \cap \{ \mathfrak{W}^*(c_{\pi^*})= \emptyset \}  \Big)
\le \eta/2,\label{UW_nonempty1}\\
&\mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})= \emptyset \} \cap \{ \mathfrak{W}^*(c_{\pi^*})\neq \emptyset \} \Big)
\le \eta/2,\label{UW_nonempty2}
\end{align}
for all $n\ge N$, where the sets in the above expressions are defined in equations \eqref{eq:set_U_NL_star} and \eqref{eq:set_W_Lpop_star}.

We begin by observing that for $j \notin \mathcal{J}^*$, $\pi^*_{1,j}=-\infty$, and therefore the corresponding inequalities 
\begin{align*}
 \left(\mathbb G^*_{n,j}(\theta_n+\tfrac{\lambda \rho }{\sqrt n})+\rho D_{P_{n},j}(\bar\theta_n)\lambda+\pi^*_{1,j}\right)(1+\eta^*_{n,j}) \le c_{n}^{*},\\  
 \mathbb{Z}^*_{j}+\rho D_{j}\lambda+\pi^*_{1,j}\le c_{\pi^*}
\end{align*}
are satisfied with probability approaching one by similar arguments as in \eqref{eq:pi_star_gamma_vanishes}. Hence, we can redefine the sets of interest as
\begin{align}
U^*_{n}(\theta_{n},c_{n}^{*})&\equiv	\big\{\lambda\in B^d_{n,\rho}: p^\prime \lambda = 0 \cap u^*_{n,j,\theta_n}(\lambda)\le c_{n}^{*}, \: \forall j \in \mathcal{J}^*\big\}, \label{eq:set_U_NL_star_new}\\
 \mathfrak W^*(c_{\pi^*})&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak{w}^*_{j}(\lambda)\le c_{\pi^*},~\forall j\in\mathcal J^*\big\}.\label{eq:set_W_Lpop_star_new}
\end{align}
We first show \eqref{UW_nonempty1}.
For this, we start by defining the events
\begin{align}
A_{ n} \equiv \left\{\sup_{\lambda \in  B^d} \max_{j \in \mathcal{J}^*}\left\vert (u^*_{n,j,\theta_n}(\lambda)-c^*_n)-( \mathfrak{w}^*_{j}(\lambda)-c_{\pi^*}) \right\vert \ge\delta  \right\}\label{eq:int2-2_2}.
\end{align}
By Lemma \ref{lem:res}, using the assumption that $\mathcal{J}^* \neq \emptyset$, for any $\eta>0$ there exists $N \in \mathbb{N}$ such that
\begin{align}

\mathbf{P}(A_{n})< \eta/2,~\forall n \ge N.\label{eq:Aln}
\end{align}
Define the sets of $\lambda$s, $U_n^{*,+\delta}$ and $\mathfrak{W}^{*,+\delta}$ by relaxing the constraints shaping  $U_n^*$ and $\mathfrak{W}^{*}$ by $\delta$:
\begin{align}
U_n^{*,+\delta}(\theta_n,c) &\equiv \{\lambda\in  B^d_{n,\rho}: p^\prime \lambda =0 \cap u^*_{n,j,\theta_n}(\lambda)\le c+\delta,~j \in \mathcal{J}^*\},\\
\mathfrak W^{*,+\delta}(c)&\equiv \{\lambda\in  \mathfrak B^d_\rho: p^\prime \lambda =0 \cap \mathfrak{w}^*_{j}(\lambda)\le c+\delta,~j \in \mathcal{J}^*\}.
\end{align}
Compared to the set in equation \eqref{eq:Wdelta}, here we replace $u^*_{n,j,\theta_n}(\lambda)$ for $u_{n,j,\theta_n}(\lambda)$ and $\mathfrak{w}^*_{j}(\lambda)$ for $\mathfrak{w}_{j}(\lambda)$, we retain only constraints in $\mathcal{J}^*$, and we relax all such constraints by $\delta>0$ instead of relaxing only those in $\{1,\dots,J_1\}$.
Next, define the event $L_{ n}\equiv\{ U_n^{*}(\theta_n,c^*_n)\subset \mathfrak W^{*,+\delta}(c_{\pi^*})\}$ and note that $A^c_{n}\subseteq L_{n}$. 

We may then bound the left hand side of \eqref{UW_nonempty1} as
\begin{align}
\mathbf{P}\Big(\{ U^*_{n}(\theta_n,c^*_n)\ne \emptyset \} \cap \{\mathfrak W^{*}(c_{\pi^*})= \emptyset \}\Big)
&\le \mathbf{P}\Big( \{ U^{*}_{n}(\theta_n,c^*_n)\ne \emptyset \} \cap \{\mathfrak W^{*,+\delta}(c_{\pi^*})=\emptyset \}\Big)\notag\\
&+\mathbf{P}\Big(\{\mathfrak W^{*,+\delta}(c_{\pi^*})\ne \emptyset \}\cap \{\mathfrak W^{*}(c_{\pi^*})=\emptyset \}\Big), \label{eq:VWres1}
\end{align}
where we used $P(A\cap B)\le P(A\cap C)+P(B\cap C^c)$ for any events $A,B,$ and $C.$ The first term on the right hand side of \eqref{eq:VWres1} can further be bounded as
\begin{align}
\mathbf{P}\Big( \{ U^{*}_{n}(\theta_n,c^*_n)\ne \emptyset \} \cap \{\mathfrak W^{*,+\delta}(c_{\pi^*})=\emptyset \}\Big)
&\le \mathbf{P}\Big(\{U^{*}_{n}(\theta_n,c^*_n)\not\subseteq\mathfrak W^{*,+\delta}(c_{\pi^*}) \} \Big) \notag\\
&= \mathbf {P}(L_{n}^c)\le\mathbf{P}(A_{n})<\eta/2,~\forall n\ge N~, \label{eq:Ato0_1}
\end{align}
where the penultimate inequality follows from $A^c_{n}\subseteq L_{n}$ as argued above, and the last inequality follows from \eqref{eq:Aln}.
For the second term on the left hand side of \eqref{eq:VWres1}, by  Lemma \ref{lem:empt}, there exists $N'\in\mathbb N$ such that
\begin{align}
\mathbf{P}\Big(\{\mathfrak W^{*,+\delta}(c_{\pi^*})\ne \emptyset \}\cap \{\mathfrak W^{*}(c_{\pi^*})=\emptyset \}\Big) \le \eta/2, ~\forall n\ge N'.\label{eq:Ato0_2}
\end{align}
Hence,  \eqref{UW_nonempty1} follows from \eqref{eq:VWres1}, \eqref{eq:Ato0_1}, and \eqref{eq:Ato0_2}.


To establish \eqref{UW_nonempty2}, we distinguish three cases.

\noindent \textbf{Case 1.} Suppose first that $J_2 = 0$ (recalling that under Assumption \ref{as:correlation}-\ref{as:correlation_pair} this means that there is no $j=1,\dots,R_1$ such that $\pi_{1,j}^*=0=\pi_{1,j+R_1}^*$), and hence one has only moment inequalities. In this case, by \eqref{eq:set_U_NL_star_new} and \eqref{eq:set_W_Lpop_star_new}, one may write
\begin{align}
	U^*_n(\theta_n,c) &\equiv \big\{\lambda\in B^d_{n,\rho}: p^\prime \lambda = 0 \cap  u^*_{n,j,\theta_n}(\lambda) \le c,~j\in \mathcal{J}^*  \big\},\\
	\mathfrak W^{*,-\delta}(c) &\equiv \big\{\lambda\in \mathfrak B^d_\rho: p^\prime \lambda =0 \cap \mathfrak{w}^*_{j}(\lambda)\le c-\delta,~j\in \mathcal{J}^*  \big\},
	\label{eq:int2-6}
\end{align}
where $\mathfrak W^{*,-\delta}$, $\delta>0$, is obtained by tightening the inequality constraints shaping $\mathfrak W^{*}$. Define the event 
\begin{align}
	R_{2 n}\equiv\{\mathfrak W^{*,-\delta}(c_{\pi^*})\subset U^*_{n}(\theta_{n},c^{*}_{n})\},\label{eq:int2-7}
\end{align}
and note that $A_{n}^c \subseteq R_{2 n}$. The result in equation \eqref{UW_nonempty2} then follows by Lemma \ref{lem:empt} using again similar steps to \eqref{eq:VWres1}-\eqref{eq:Ato0_2}. 


\noindent \textbf{Case 2.} Next suppose that $J_2\ge d$. In this case,  we define $\mathfrak W^{*,-\delta}$ to be the set obtained by tightening by $\delta$ the inequality constraints as well as each of the two opposing inequalities obtained from the equality constraints.
That is, 
\begin{align}
	\mathfrak W^{*,-\delta}(c_{\pi^*}) &\equiv \{\lambda\in  \mathfrak B^d_\rho: p^\prime \lambda =0 \cap \mathfrak{w}^*_{j}(\lambda)\le c-\delta,~j \in \mathcal{J}^*\},\label{eq:int2-8}
\end{align}
that is, the same set as in \eqref{eq:Wdelta_lb_c} with $\mathfrak{w}^*_{j}(\lambda)$ replacing $\mathfrak{w}_{j}(\lambda)$ and defining the set using only inequalities in $\mathcal{J}^*$.
Note that, by Lemma \ref{lem:cbd}, there exists $N \in \mathbb{N}$ such that for all $n \ge N$ $c^I_n(\theta)$ is bounded from below by some $\underline{c}>0$ with probability approaching one uniformly in $P \in \mathcal{P}$ and $\theta \in \Theta_I(P)$. This ensures  $c_{\pi^*}$ is bounded from below by $\underline{c}>0$.
This in turn allows us to construct a non-empty tightened constraint set with probability approaching 1.
Namely, for $\delta<\underline{c}$,  $\mathfrak W^{*,-\delta}(c_{\pi^*})$ is nonempty with probability approaching 1 by Lemma \ref{lem:empt},  and hence its superset $\mathfrak W^{*}(c_{\pi^*})$  is also non-empty with probability approaching 1. However, note that $A_{n}^c \subseteq R_{2 n}$, where $R_{2 n}$ is in \eqref{eq:int2-7} now defined using the tightened constraint set $\mathfrak W^{*,-\delta}(c_{\pi^*}) $ being defined as in \eqref{eq:int2-8}, and therefore the same argument as in the previous case applies.

\noindent \textbf{Case 3.} Finally, suppose that $1\le J_2 <d$. Recall that, with probability 1 (under $\mathbf P$),
\begin{align}
c_{\pi^*}=\lim_{n \to \infty}c^*_{n},\label{eq:tilde_c_lim}
\end{align}
and note that by construction $c_{\pi^*}\ge0.$ 
Consider first the case that $c_{\pi^*}>0$. Then, by taking $\delta< c_{\pi^*}$, the argument in Case 2 applies.

Next consider the case that $c_{\pi^*}=0$.  
Observe that
\begin{align}
&~\mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})= \emptyset \} \cap \{ \mathfrak W^*(c_{\pi^*})\neq \emptyset \} \Big) \\
\le &~ \mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})= \emptyset \} \cap \{ \mathfrak W^{*,-\delta}(0)\neq \emptyset \} \Big) +\mathbf{P}\Big(\{\mathfrak W^{*,-\delta}(0)= \emptyset \} \cap \{ \mathfrak W^*(0)\neq \emptyset \} \Big),
\label{eq:W_lim_U1}
\end{align}
with $\mathfrak W^{*,-\delta}(0)$ defined as in \eqref{eq:Wdelta} with $c=0$ and with $\mathfrak{w}^*_{j}(\lambda)$ replacing $\mathfrak w_{j}(\lambda)$.
By Lemma \ref{lem:empt}, for any $\eta>0$ there exists $\delta>0$ and $N \in \mathbb{N}$ such that
\begin{align}
\mathbf{P}\Big(\{\mathfrak W^{*,-\delta}(0)= \emptyset \} \cap \{\mathfrak W^*(0)\neq \emptyset \} \Big)<\eta/3 \text{  for all } n\ge N.\label{eq:final2}
\end{align}
Therefore, the second term on the right hand side of \eqref{eq:W_lim_U1} can be made arbitrarily small. 


We now consider the first term  on the right hand side of \eqref{eq:W_lim_U1}. 
Let $g$ be a $J+2d+2$ vector with
 \begin{align}
 g_{j} =\left\{ \begin{array}{lll}
   - \mathbb{Z}_j, &  j\in \mathcal J^*,\\
  0, & j\in\{1,\cdots,J\}\setminus \mathcal J^*,\\
  1, &  j=J+1,\dots,J+2d,\\
 0, & j=J+2d+1,J+2d+2,
 	\end{array} 
 	\right. \label{eq:g}
 \end{align}
where we used that $\pi_{1,j}^*=0$ for $j\in\mathcal{J}^*$ and where the last assignment is without loss of generality because of the considerations leading to the sets in \eqref{eq:set_U_NL_star_new}-\eqref{eq:set_W_Lpop_star_new}. 

For a given set $C \subset \{1,\dots,J+2d+2\}$, let the vector $g^C$ collect the entries of $g^C$ corresponding to indices in $C$. 
Let \begin{align}
K  \equiv 
\begin{bmatrix}
[\rho D_{j}]_{j=1}^{J_1+J_2}\\
[-\rho D_{j-J_2}]_{j=J_1+J_2+1}^J\\
I_d\\
-I_d\\
p^\prime\\
-p^\prime
\end{bmatrix}. 
\end{align}
Let the matrix $K^C$ collect the rows of $K$ corresponding to indices in $C$.

Let $\widetilde{\mathcal{C}}$ collect all size $d$ subsets $C$ of $\{1,...,J+2d+2\}$ ordered
lexicographically by their smallest, then second smallest, etc. elements.
Let the random variable $\mathcal{C}$  equal the first element of $\widetilde{\mathcal{C}}$ s.t. $\det K^C\neq 0$ and $\lambda^{C}=( K^C)
^{-1}g^C\in \mathfrak W^{* ,-\delta }(0)$ if such an
element exists; else, let $\mathcal{C}=\{J+1,...,J+d\}$ and $\lambda^{C}= \mathbf{1}_d$, where $\mathbf{1}_d$ denotes a $d$ vector with each entry equal to $1$. Recall that $\mathfrak W^{* ,-\delta }(0)$ is a (possibly empty) measurable random polyhedron in a compact subset of $\mathbb{R}^{d}$, see, e.g., \citet[Definition 1.1.1]{mo1}. Thus, if $\mathfrak W^{* ,-\delta }(0)\neq \emptyset$, then $\mathfrak W^{* ,-\delta }(0)$ has extreme points, each of which is characterized as the intersection of $d$ (not necessarily unique) linearly independent constraints interpreted
as equalities. Therefore, $\mathfrak W^{* ,-\delta }(0)\neq
\emptyset $ implies that $\lambda ^{\mathcal{C}}\in \mathfrak W^{* ,-\delta }(0)$ and therefore also that $\mathcal{C}\subset \mathcal{J}^* \cup \{J+1,\dots,J+2d+2\}$. Note that the associated random vector $\lambda^{\mathcal{C}}$ is a measurable selection of a random closed set that equals $\mathfrak W^{*,-\delta}(0)$ if $\mathfrak W^{*,-\delta}(0)\neq \emptyset$ and equals $\mathfrak B^d_\rho$ otherwise, see, e.g., \citet[Definition 1.2.2]{mo1}.

Lemma \ref{lem:exist_sol} establishes that for any $\eta >0$, there exist $\varepsilon_\eta>0$
and $N$ s.t. $n\geq N$ implies
\begin{align}
\mathbf{P} \left( \mathfrak W^{*,-\delta}(0) \neq
\emptyset ,\left\vert \det K^{\mathcal{C}}\right\vert \leq \varepsilon_\eta\right) \leq \eta,\label{eq:det_bound}
\end{align}
 which in turn, given our definition of $\mathcal{C}$,  yields that there is $M>0$ and $N$ such that
\begin{align}
\mathbf P\Big(\big|\det \left(K^{\mathcal{C}}\right)^{-1} \big|\le M\Big)\ge 1-\eta,~\forall n\ge N. \label{eq:det_inv_Op1}
\end{align}

Let $g_n$ be a $J+2d+2$ vector with
\begin{align}
\label{eq:tilde_g}
g_{n,j}(\theta+\lambda/\sqrt{n})\equiv \left\{ \begin{array}{llll}
c^{*}_{n}/(1+\eta^*_{n,j})-\mathbb{G}^*_{n,j}(\theta+\frac{\lambda \rho }{\sqrt n}) &  \mathrm{if}~j \in \mathcal{J}^*,\\
0, & \mathrm{if}~j\in\{1,\cdots,J\}\setminus\mathcal{J}^*,\\
1, &  \mathrm{if}~j=J+1,\dots,J+2d,\\
0, & \mathrm{if}~j=J+2d+1,J+2d+2,\\
	\end{array} 
	\right. 
\end{align}
using again that $\pi_{1,j}^*=0$ for $j \in \mathcal{J}^*$. For each $P\in\mathcal P$, let
\begin{align}
K_P(\theta,\rho) \equiv 
\begin{bmatrix}
[\rho D_{P,j}(\theta)]_{j=1}^{J_1+J_2}\\
[-\rho D_{P,j-J_2}(\theta)]_{j=J_1+J_2+1}^J\\
I_d\\
-I_d\\
p^\prime\\
-p^\prime
\end{bmatrix}. \label{eq:KP}
\end{align}
For each $n$ and $\lambda \in B^d$, define the mapping $\phi_{n}:B^d\to \mathbb{R}^d_{[\pm \infty]}$ by
\begin{align}
\label{eq:phi_fp}
\phi_{n}(\lambda) \equiv \left(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\right)^{-1} g^{\mathcal{C}}_{n}(\theta_{n} + \tfrac{\lambda \rho }{\sqrt n}),
\end{align}
where the notation $\bar\theta(\theta_n,\lambda)$ emphasizes that $\bar{\theta}$ depends on $\theta_n$ and $\lambda$ because it lies component-wise between $\theta_n$ and $\theta_n + \frac{\lambda \rho }{\sqrt n}$.
We show that $\phi_{n}$ is a contraction mapping and hence has a fixed point.

For any $\lambda,\lambda^\prime \in B^d$ write
\begin{align}
\Vert \phi_{n}(\lambda) - \phi_{n}(\lambda^\prime) \Vert \notag&= \Big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1}g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})- \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda^\prime),\rho )\big)^{-1}g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \Big\Vert \notag\\
&\le \Big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1} \Big\Vert_2 \Big\Vert g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \Big\Vert \notag\\
&\qquad+\Big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1}- \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda^\prime),\rho )\big)^{-1}\Big\Vert_2 \Big\Vert g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \Big\Vert,\label{eq:phi_decomp}
\end{align}
where $\|\cdot\|_2$ denotes the spectral norm (induced by the Euclidean norm).

By Assumption \ref{as:bcs1} (ii), for any $\eta>0$, $k>0$, there is $N\in\mathbb N$ such that
\begin{align}
&~\mathbf P\left(\left\Vert g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \right\Vert\le k\|\lambda-\lambda'\|\right) \\ 
=&~\mathbf P\left(\left\|\mathbb G^{*,{\mathcal{C}}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})-\mathbb G^{*,{\mathcal{C}}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}})\right\|\le k\|\lambda-\lambda'\|\right)\ge 1-\eta,~\forall n\ge N.\label{eq:g_gprimeOrootn}
\end{align}
Moreover, by arguing as in equation \eqref{eq:pi_star_gamma_vanishes}, for any $\eta$ there exist $0<L<\infty$ and $N\in\mathbb N$ such that $\forall n\ge N$
\begin{align}
\mathbf P\left(\sup_{\lambda^\prime \in B^d}\left\Vert g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \right\Vert\le L\right) \ge 1-\eta.\label{eq:g_O1}
\end{align}
For any invertible matrix $K$, $\|K^{-1}\|_2=\left(\min \{\sqrt{\alpha}:~\alpha ~\text{ is an eigenvalue of } KK^\prime \}\right)^{-1}$.
Hence, by the proof of Lemma \ref{lem:exist_sol} and the definition of $\mathcal{C}$, for any $\eta>0$, there exist $0<L<\infty$ and $N\in\mathbb N$ such that
\begin{align}
\mathbf P\big(\big\Vert \big(K^{\mathcal{C}} \big)^{-1} \big\Vert_2 \le L \big)\ge  1-\eta,~\forall n\ge N,\label{eq:boundKn_inv2}
\end{align}
By \citet[ch. 5.8]{HornJohnson}, for any invertible matrices $K,\tilde K$ such that $\|\tilde K^{-1}(K-\tilde K)\|_2<1$, 
\begin{align}
	\| K^{-1}-\tilde K^{-1}\|_2\le \frac{\|\tilde K^{-1}(K-\tilde K)\|_2}{1-\|\tilde K^{-1}(K-\tilde K)\|_2}\|\tilde K^{-1}\|_2.
	\label{eq:boundKn_inv2a}
\end{align}
By the assumption that $D_{P_n}(\theta_n)\to D$ and Assumption \ref{as:momP_KMS}, for any $\eta>0$, there exists $N\in\mathbb N$ such that
\begin{align}
\sup_{\lambda\in B^d}\|K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )-K^{\mathcal{C}}\|_2 \le \eta,~\forall n\ge N.
\end{align}  
By \eqref{eq:boundKn_inv2a}, the definition of the spectral norm, and the triangle inequality, for any $\eta>0$, there exist $0<L_1,L_2<\infty$ and $N\in\mathbb N$ such that
\begin{align}
&~\mathbf P \big(\sup_{\lambda\in B^d}\big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho ) \big)^{-1} \big\Vert_2 \le 2L_1\big)\notag\\
\ge&~ \mathbf P\big(\big\Vert \big(K^{\mathcal{C}} \big)^{-1} \big\Vert_2+\sup_{\lambda\in B^d}\|K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )^{-1}-(K^{\mathcal{C}})^{-1}\|_2 \le 2L_1 \big)\notag	\\
\ge &~\mathbf P\Bigg(\big\Vert \big(K^{\mathcal{C}} \big)^{-1} \big\Vert_2\le L_1 , \frac{\Vert \big( K^{\mathcal{C}}\big)^{-1}\Vert_2^2}{1-\|\big( K^{\mathcal{C}}\big)^{-1}(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )-K^{\mathcal{C}})\|_2}\le L_2,~\sup_{\lambda\in B^d}\|K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )-K^{\mathcal{C}}\|_2 \le \frac{L_1}{L_2} \Bigg)\notag\\
\ge & ~ 1-2\eta,~\forall n\ge N,	\label{eq:boundKn_inv2b}
\end{align}
Again by applying \eqref{eq:boundKn_inv2a}, for any $k>0$, there exists $N\in\mathbb N$ such that
\begin{align}
	&~\mathbf P\big(\big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda))\big)^{-1}- \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda^\prime))\big)^{-1}\big\Vert_2\le k\|\lambda-\lambda'\|\big)
	\\
	\ge&~ \mathbf P\Big(\sup_{\lambda\in B^d}\big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda)) \big)^{-1} \big\Vert_2^2 M \rho \|\bar\theta(\theta_{n},\lambda)-\bar\theta(\theta_{n},\lambda^\prime)\|\le k\|\lambda-\lambda'\| \Big)\ge 1-\eta,~\forall n\ge N,\label{eq:boundKn_inv2c}
\end{align}
where the first inequality follows from $\|K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda))-K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda'))\|_2\le M\rho \|\bar\theta(\theta_{n},\lambda)-\bar\theta(\theta_{n},\lambda^\prime)\|\le M\rho ^2/\sqrt n\|\lambda-\lambda'\|$ by Assumption \ref{as:momP_KMS} (ii), and the last inequality follows from \eqref{eq:boundKn_inv2b}.

By \eqref{eq:phi_decomp}-\eqref{eq:g_O1} and \eqref{eq:boundKn_inv2b}-\eqref{eq:boundKn_inv2c}, it then follows that
 there exists $\beta \in [0,1)$ such that for any $\eta>0$, there exists $N \in \mathbb{N}$ such that
\begin{align}
\mathbf{P}\left(\vert \phi_{n}(\lambda) - \phi_{n}(\lambda^\prime) \vert \le \beta \Vert \lambda - \lambda^\prime \Vert, ~~\forall \lambda,\lambda^\prime \in B^d\right) \ge 1-\eta, ~\forall n\ge N. \label{eq:contraction}
\end{align}
This implies that with probability approaching 1, each $\phi_{n}(\cdot)$ is a contraction, and therefore by the Contraction Mapping Theorem it has a fixed point (e.g., \citet[Theorem 1.3]{Pata}). This in turn implies that for any $\eta>0$ there exists a $N \in \mathbb{N}$ such that
\begin{align}
\mathbf{P}\left(\exists \lambda^f_{n}: \lambda^f_{n} = \phi_{n}(\lambda^f_{n})  \right) \ge 1-\eta, ~\forall n\ge N. \label{eq:fixed_point}
\end{align}


Next, define the mapping
\begin{equation}
\psi_{n}(\lambda) \equiv \left( K^{\mathcal{C}} \right)^{-1}g^{\mathcal{C}}. \label{eq:limit_map}
\end{equation}
This map is constant in $\lambda$ and hence is uniformly continuous and a contraction with Lipschitz constant equal to zero. It therefore has $\lambda^{\mathcal{C}}_{n}$ as its fixed point. Moreover, by \eqref{eq:phi_fp} and \eqref{eq:limit_map} arguing as in \eqref{eq:phi_decomp}, it follows that for any $\lambda\in B^d$,
\begin{align}
\Vert \psi_{n}(\lambda) -\phi_{n}(\lambda)\Vert&\le 	\Big\Vert \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1} \Big\Vert_2 \Big\Vert g^{\mathcal{C}}- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n}) \Big\Vert 
+\Big\Vert \big(K^{\mathcal{C}}\big)^{-1}- \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1}\Big\Vert_2 \big\Vert g^{\mathcal{C}} \big\Vert.
\end{align}
By \eqref{eq:g} and \eqref{eq:tilde_g} 
\begin{align}
 \Big\Vert g^{\mathcal{C}}- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n}) \Big\Vert
 &\le \max_{j \in \mathcal{J}^*}|- \mathbb{Z}_j^*-c^{*}_{n}/(1+\eta^*_{n,j})+\mathbb{G}^*_{n,j}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})|\notag\\
 &\le \max_{j \in \mathcal{J}^*}|\mathbb{Z}_j^* -\mathbb{G}^*_{n,j}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})|+\max_{j \in \mathcal{J}^*}|c^{*}_{n}/(1+\eta^*_{n,j})|.\label{eq:psiphi1}
\end{align}
We note that when Assumption \ref{as:correlation}-\ref{as:correlation_pair} is used, for each $j=1,\dots,R_1$ such that $\pi^*_{1,j}=0=\pi^*_{1,j+R_1}$ we have that $\vert \tilde{\mu}_j -\mu_j \vert = o_\mathcal{P}(1)$ because $\sup_{\theta \in \Theta}\vert\eta_j(\theta)\vert=o_\mathcal{P}(1)$, where $\tilde{\mu}_j $ and $\mu_j$ were defined in \eqref{eq:tilde_weight_j}-\eqref{eq:tilde_weight_j_pl_J11} and \eqref{eq:weight_j}-\eqref{eq:weight_j_pl_J11} respectively.
Moreover,  $\mathbb{G}^*_{n,j}(\theta_{n}+\frac{\lambda \rho }{\sqrt n})\stackrel{a.s.}{\to}\mathbb \mathbb{Z}^*$  and \eqref{eq:tilde_c_lim} implies $c^{*}_{n} \to 0$ so that we have 
\begin{align}
\sup_{\lambda\in B^d} \Bigl\Vert g^{\mathcal{C}}- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n}) \Bigr\Vert\stackrel{a.s.}{\to}0.	\label{eq:psiphi2}
\end{align}
Further, by \eqref{eq:boundKn_inv2a}, $D_{P_n}\to D$ and, Assumption \ref{as:momP_KMS}-(ii), for any $\eta>0$, there exists $N\in\mathbb N$ such that
\begin{align}
\sup_{\lambda\in B^d}	\Big\Vert \big(K^{\mathcal{C}}\big)^{-1}- \big(K_{P_{n}}^{\mathcal{C}}(\bar\theta(\theta_{n},\lambda),\rho )\big)^{-1}\Big\Vert_2 \le \eta,~\forall n\ge N.\label{eq:psiphi3}
\end{align}
In sum, by \eqref{eq:g_O1}, \eqref{eq:boundKn_inv2b}, and \eqref{eq:psiphi1}-\eqref{eq:psiphi3}, for any $\eta,\nu>0$, there exists $N\ge\mathbb N$ such that
\begin{align}
\mathbf{P}\left(\sup_{\lambda \in B^d}\Vert \psi_{n}(\lambda) -\phi_{n}(\lambda)\Vert<\nu\right)\ge 1-\eta,~\forall n\ge \mathbb N.\label{eq:unif_conv_phi}
\end{align}  
Hence, for a specific choice of $\nu=\kappa(1-\beta)$, where $\beta$ is defined in equation \eqref{eq:contraction}, we have that $\sup_{\lambda \in B^d}\Vert \psi_{n}(\lambda) -\phi_{n}(\lambda)\Vert<\kappa(1-\beta)$ implies
\begin{align}
\Vert \lambda^{\mathcal{C}}_{n} - \lambda^f_{n} \Vert &= \Vert \psi_{n}(\lambda^{\mathcal{C}}_{n}) -\phi_{n}(\lambda^f_{n})\Vert\notag\\
&\le \Vert \psi_{n}(\lambda^{\mathcal{C}}_{n}) -\phi_{n}(\lambda^{\mathcal{C}}_{n})\Vert+\Vert \phi_{n}(\lambda^{\mathcal{C}}_{n}) -\phi_{n}(\lambda^f_{n})\Vert\notag\\
&\le \kappa(1-\beta) + \beta \Vert \lambda^{\mathcal{C}}_{n} - \lambda^f_{n} \Vert
\end{align}
Rearranging terms, we obtain $\Vert \lambda^{\mathcal{C}}_{n} - \lambda^f_{n} \Vert \le \kappa$. 
Note that by Assumptions \ref{as:momP_KMS} (i) and \ref{as:bcs1} (i),  for any $\delta>0$, there exists $\kappa_\delta>0$ and $N\in\mathbb N$ such that 
\begin{align}
\mathbf P\Big(\sup_{\|\lambda-\lambda'\|\le \kappa_\delta}	|u^*_{n,j,\theta_{n}}(\lambda)-u^*_{n,j,\theta_{n}}(\lambda')|<\delta\Big)\ge 1-\eta,~\forall n\ge \mathbb N.	\label{eq:se_u}
\end{align}
For $\lambda^{\mathcal{C}}_{n}\in \mathfrak W^{*,-\delta}(0)$, one has
\begin{align}
	\mathfrak w^*_{j}(\lambda^{\mathcal{C}}_{n})+\delta\le 0,~j \in \{1,\cdots, J_1\} \cap \mathcal{J}^*.\label{eq:wconst}
\end{align}
Hence, by \eqref{eq:Aln}, \eqref{eq:tilde_c_lim}, and \eqref{eq:se_u}-\eqref{eq:wconst}, $\Vert \lambda^{\mathcal{C}}_{n} - \lambda^f_{n} \Vert \le \kappa_{\delta/4}$, for each $j \in \{1,\cdots, J_1\} \cap \mathcal{J}^*$ we have
\begin{align}
	u^*_{n,j,\theta_{n}}(\lambda^f_{n})-c^{*}_{n}(\theta_n)\le u^*_{n,j,\theta_{n}}(\lambda^{\mathcal{C}}_{n})-c^{*}_{n}(\theta_n)+\delta/4 \le \mathfrak w^*_{j}(\lambda^{\mathcal{C}}_{n})+\delta/2 \le 0.
\end{align}
For $j \in \{J_1+1,\cdots, 2J_2\} \cap \mathcal{J}^*$, the inequalities hold by construction given the definition of ${\mathcal{C}}$.

 In sum, for any $\eta>0$ there exists $\delta > 0$ and  $N \in \mathbb{N}$ such that for all $n \ge N$ we have
 \begin{align}
\mathbf{P}\Big( \{U^*_{n}(\theta_{n},c^{*}_{n})= \emptyset \} \cap \{\mathfrak W^{*,-\delta}(0)\neq \emptyset \} \Big)
\le \mathbf{P}	\Big(\nexists \lambda^f_{n}\in U^*_{n}(\theta_{n},c^{*}_{n}), \exists \lambda^{\mathcal{C}}_{n}\in \mathfrak W^{*,-\delta}(0) \Big)& \notag \\
\le \mathbf{P}	\left(\left\{\sup_{\lambda \in  B^d}\Vert \psi_{n}(\lambda) -\phi_{n}(\lambda)\Vert<\kappa_\delta(1-\beta) \cap A_{n} \right\}^c \right)\le \eta/3,&\label{eq:final1}
 \end{align}
where $A^c$ denotes the complement of the set $A$, and the last inequality follows from \eqref{eq:Aln} and \eqref{eq:unif_conv_phi}.

