U^*_{n}(\theta_{n},c_{n}^{*})&\equiv	\big\{\lambda\in B^d_{n,\rho}: p^\prime \lambda = 0 \cap u^*_{n,j,\theta_n}(\lambda)\le c_{n}^{*}, \: \forall j \in \mathcal{J}^*\big\}, \label{eq:set_U_NL_star_new}\\
 \mathfrak W^*(c_{\pi^*})&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak{w}^*_{j}(\lambda)\le c_{\pi^*},~\forall j\in\mathcal J^*\big\}.\label{eq:set_W_Lpop_star_new}
