&~\mathbf P\left(\left\Vert g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})- g^{\mathcal{C}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}}) \right\Vert\le k\|\lambda-\lambda'\|\right) \\ 
=&~\mathbf P\left(\left\|\mathbb G^{*,{\mathcal{C}}}_{n}(\theta_{n}+\tfrac{\lambda \rho }{\sqrt n})-\mathbb G^{*,{\mathcal{C}}}_{n}(\theta_{n}+\tfrac{\lambda^\prime \rho }{\sqrt{n}})\right\|\le k\|\lambda-\lambda'\|\right)\ge 1-\eta,~\forall n\ge N.\label{eq:g_gprimeOrootn}
