\end{align}

\label{lem:cv_convergence}
Suppose Assumptions \ref{as:momP_AS}, \ref{as:GMS},  \ref{as:correlation}, \ref{as:momP_KMS}, and \ref{as:bcs1} hold.
Let	$\{P_n,\theta_n\} \in \{(P,\theta):P \in \mathcal{P},\theta \in \Theta_I(P)\}$ be a sequence satisfying \eqref{eq:subseq1}-\eqref{eq:subseq3}. 
For each $j$, let
\begin{align}
v^I_{n,j,\theta_n}(\lambda)&\equiv	\mathbb G^b_{n,j}(\theta_n)+\rho\hat{D}_{n,j}(\theta_n)\lambda+\varphi^*_j(\hat{\xi}_{n,j}(\theta_n)),\label{eq:vIj_var}\\
\mathfrak{w}_{j}(\lambda)&\equiv \mathbb{Z}_{j}+\rho D_{j}\lambda+\pi^*_{1,j},
\end{align}
where 
\begin{align}
\varphi^*_j(\xi)=\begin{cases}
	\varphi_j(\xi)&\pi_{1,j}=0\\
	-\infty&\pi_{1,j}<0\\
	0&j=J_1+1,\cdots,J.
\end{cases}\label{eq:greedy_gms}	
\end{align}
For each $c\ge0$, define
\begin{align}
V^I_n(\theta_n,c)&\equiv \{\lambda\in B^d_{n,\rho}:p'\lambda=0\cap v^I_{n,j,\theta_n}(\lambda)\le c,j=1,\cdots,J\},\label{eq:VIn}\\
\mathfrak{W}(c)&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak w_{j}(\lambda)\le c, \: \forall j=1,\dots,J\big\}.
\end{align}
We then let $c^I_n(\theta_n)\equiv \inf\{c\in\mathbb{R}_+:P^*_n(V^I_n(\theta_n,c)\neq \emptyset)\ge 1-\alpha\}$ and $c_{\pi^*}\equiv \inf\{c\in\mathbb R_+:\Pr(\mathfrak{W}(c)\ne\emptyset)\ge 1-\alpha\}$.

Then, 
(i) for any $c>0$ and $\{\theta'_n\}\subset\Theta$ such that $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for all $n$, 
\begin{align}
P^*_n(V^I_n(\theta'_n,c)\ne\emptyset)-	\Pr(\mathfrak{W}(c)\ne\emptyset)\to 0,
\end{align}	
with probability approaching 1; 

\noindent
(ii)  If $c_{\pi^*}>0$, $c^I_n(\theta'_n)\stackrel{P_n}{\to}c_{\pi^*};$ 

\noindent
(iii) For any $\{\theta'_n\}\subset\Theta$ such that $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for all $n$,
\begin{align}
\hat c_n(\theta'_n)\ge c^I_n(\theta'_n)+o_{P_n}(1).	
\end{align}

\begin{align}
V^I_n(\theta_n,c)&\equiv \{\lambda\in B^d_{n,\rho}:p'\lambda=0\cap v^I_{n,j,\theta_n}(\lambda)\le c,j=1,\cdots,J\},\label{eq:VIn}\\
\mathfrak{W}(c)&\equiv \big\{ \lambda\in \mathfrak B^d_\rho: p^\prime \lambda = 0 \cap \mathfrak w_{j}(\lambda)\le c, \: \forall j=1,\dots,J\big\}.
\end{align}

	Throughout, let $c>0$ and let $\{\theta'_n\}\subset\Theta$ be a sequence such that $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for all $n$.
By Lemma \ref{lem:boot_cons}, 
 in $l^\infty(\Theta)$ uniformly in $\mathcal{P}$ conditional on $\{X_i\}_{i=1}^\infty$, and by Assumption \ref{as:momP_KMS} $\|\hat D_n(\theta_n')-D_{P_n}(\theta_n)\|\stackrel{p}{\to} 0$.
 Further, by Lemma \ref{lem:Jstar}, $\hat{\xi}_{n,j}(\theta_n')\stackrel{P_n}{\to}\pi_{1,j}.$ Therefore,
\begin{align}
(\mathbb G^b_{n}(\theta'_n),\hat D_{n}(\theta_{n}'), \hat\xi_{n}(\theta_n'))|\{X_i\}_{i=1}^\infty\stackrel{d}{\to}(\mathbb{Z},D, \pi_1).\label{eq:asrep_invoke}
\end{align}
for almost all sample paths $\{X_i\}_{i=1}^\infty$. By Lemma \ref{cor:asrep}, conditional on the sample path, there exists an almost sure representation $(\tilde{\mathbb G}^{b}_{n}(\theta'_n),\tilde D_n,\tilde{\xi}_{n})$ of $(\mathbb G^b_{n}(\theta'_n),\hat{D}_{n}(\theta'_n),\hat{\xi}_{n}(\theta'_n))$ defined on another probability space $(\tilde \Omega,\tilde{\mathcal F},\tilde{\mathbf P})$ such that $(\tilde{\mathbb G}^{b}_{n}(\theta'_n),\tilde D_n,\tilde{\xi}_{n})\stackrel{d}{=}(\mathbb G^b_{n}(\theta'_n),\hat{D}_{n}(\theta'_n),\hat{\xi}_{n}(\theta'_n))$ conditional on the sample path. In particular, conditional on the sample, $(\hat{D}_{n}(\theta'_n),\hat{\xi}_{n}(\theta'_n))$ are non-stochastic. Therefore, we set $(\tilde D_n,\tilde{\xi}_{n})\stackrel{}{=}(\hat{D}_{n}(\theta'_n),\hat{\xi}_{n}(\theta'_n))$, $\tilde{\mathbf P}-a.s$. 
The almost sure representation satisfies
$(\tilde{\mathbb G}^b_{n}(\theta'_n),\tilde D_{n},\tilde{\xi}_{n,j})\stackrel{a.s.}{\to} (\tilde\mathbb{Z},D, \pi_1)$ for almost all sample paths, where $\tilde\mathbb{Z}\stackrel{d}{=}\mathbb{Z}$. The almost sure representation $(\tilde{\mathbb G}^b_{n},\tilde D_n,\tilde{\xi}_{n})$ is defined for each sample path $x^\infty=\{x_i\}_{i=1}^\infty$, but we suppress its dependence on $x^\infty$ for notational simplicity (see Appendix \ref{app:asrep} for details).
Using this representation, define
\begin{align}
\tilde v^I_{n,j,\theta'_n}(\lambda)\equiv	\tilde{\mathbb G}^b_{n,j}(\theta'_n)+\rho\tilde D_n\lambda+\varphi^*_j(\tilde{\xi}_{n,j}),\label{cv_conv1}
\end{align}and
\begin{align}
\tilde{\mathfrak{w}}_{j}(\lambda)&\equiv \tilde \mathbb{Z}_j+ \rho D_{j}\lambda+\pi^*_{1,j},\label{cv_conv2}
\end{align}
where $\tilde{\mathbb Z}\stackrel{d}{=}\mathbb Z$, and $\tilde{\mathbb G}^b_{n}(\theta'_n)\to \tilde{\mathbb Z}, \tilde{\mathbf P}-a.s.$ conditional on $\{X_i\}_{i=1}^\infty$.
With this construction, one may write
\begin{multline}
|P^*_n(V^I_n(\theta'_n,c)\ne \emptyset)-	\Pr(\mathfrak{W}(c)\ne\emptyset)|=|\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)\ne\emptyset)-	\tilde{\mathbf P}(\tilde{\mathfrak{W}}(c)\ne\emptyset)|\label{eq:cv_conv3}\\
\le |\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)+\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)\ne \emptyset\cap\tilde{\mathfrak{W}}(c)=\emptyset)|,
\end{multline}	
where the inequality is due to \eqref{eq:cover5}.
First,  we  bound  the first term on the right hand side of \eqref{eq:cv_conv3}. Note that
\begin{align}
\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)
\le 	\tilde{\mathbf P}(\tilde V^{I,+\delta}_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)+\tilde{\mathbf P}(\tilde V^{I,+\delta}_n(\theta'_n,c)\ne\emptyset\cap\tilde V^I_n(\theta'_n,c)=\emptyset),\label{eq:cv_conv4}
\end{align}
where $\tilde V^{I,+\delta}_n$ is defined as
\begin{align}
\tilde V^{I,+\delta}_n\equiv \Big\{\lambda\in B^d_{n,\rho}:p'\lambda=0\cap\tilde v^I_{n,j,\theta'_n}(\lambda)\le c+\delta,j\in\mathcal J^*\Big\}.
\end{align}
Let 
\begin{align}
A_n\equiv\Big\{\tilde\omega\in\tilde\Omega:\sup_{\lambda\in B^d}\max_{j\in\mathcal J^*}|\tilde v^I_{n,j,\theta'_n}(\lambda)-\tilde{\mathfrak{w}}_{j}(\lambda)|\ge\delta\Big\}.\label{eq:cv_conv5}
\end{align}
Let 
\begin{align}
E\equiv \{\{x_i\}_{i=1}^\infty:\|\hat D_{n}(\theta'_n)-D\|<\eta,\max_{j\in\mathcal J^*}|\varphi_j^*(\hat{\xi}_{n,j}(\theta'_n))-\pi^*_{1,j}|<\eta\}.\label{eq:cv_conv6}	
\end{align}
Note that, $P_n(E)\ge 1-\eta$ for all $n$ sufficiently large by Assumption \ref{as:momP_KMS} and Lemma \ref{lem:Jstar}. On $E$, we therefore have $\|\tilde D_n-D\|<\eta$ and $\max_{j\in\mathcal J^*}|\tilde{\xi}_{n,j}-\pi^*_{1,j}|<\eta$, $\tilde{\mathbf P}-a.s.$ 
Below, we condition on  $\{X_i\}_{i=1}^\infty\in E$. For any $j\in\mathcal J^*$,
\begin{align}
|\tilde v^I_{n,j,\theta'_n}(\lambda)-\tilde{\mathfrak{w}}_{j}(\lambda)|\le |\tilde{\mathbb G}^b_{n,j}(\theta'_n)-\tilde \mathbb{Z}_j|+\rho\|\tilde D_{j,n} -D_{j}\|\|\lambda\|+|\varphi_j^*(\tilde{\xi}_{n,j})-\pi^*_{1,j}|\le (2+\rho)\eta,\label{eq:use-of-lambda}
\end{align}
uniformly in $\lambda\in B^d$, where we used $\tilde{\mathbb G}^b_{n}\to \tilde{\mathbb Z}, \tilde{\mathbf P}-a.s.$
Since $\eta$ can be chosen arbitrarily small, this in turn implies
\begin{align*}
\tilde{\mathbf P}\big(A_n\big)<\eta/2,
\end{align*}
for all $n$ sufficiently large. Note also that
$\sup_{\lambda\in B^d}\max_{j\in\mathcal J^*}|\tilde v^I_{n,j,\theta'_n}(\lambda)-\tilde{\mathfrak{w}}_{j}(\lambda)|<\delta$ implies $\tilde{\mathfrak{W}}(c)\subseteq\tilde V^{I,+\delta}_n(\theta'_n,c)$, and hence
 $A^c_n$ is a subset of
\begin{align}
L_n\equiv\Big\{\tilde\omega\in\tilde\Omega:\tilde{\mathfrak{W}}(c)\subseteq\tilde V^{I,+\delta}_n(\theta'_n,c)\Big\}.\label{eq:cv_conv7}
\end{align}
Using this,
\begin{align}
\tilde{\mathbf P}(\tilde V^{I,+\delta}_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)\le \tilde{\mathbf P}(\tilde{\mathfrak{W}}(c)\not\subseteq\tilde V^{I,+\delta}_n(\theta'_n,c))
=\tilde{\mathbf P}(L^c_n)\le \tilde{\mathbf P}(A_n)<\eta/2,\label{eq:cv_conv8}
\end{align}
for all $n$ sufficiently large.
Also, by Lemma \ref{lem:empt},
\begin{align}
\tilde{\mathbf P}(\tilde V^{I,+\delta}_n(\theta'_n,c)\ne\emptyset\cap\tilde V^I_n(\theta'_n,c)=\emptyset)<\eta/2,\label{eq:cv_conv9}
\end{align}
for all $n$ sufficiently large. 


Combining \eqref{eq:cv_conv4}, \eqref{eq:cv_conv5}, \eqref{eq:cv_conv8}, \eqref{eq:cv_conv9}, and using $P_n(E)\ge 1-\eta$ for all $n$, we have
\begin{equation}
\int_{E}\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)dP_n+\int_{E^c}\tilde{\mathbf P}(\tilde V^I_n(\theta'_n,c)=\emptyset\cap\tilde{\mathfrak{W}}(c)\ne\emptyset)dP_n\le \eta(1-\eta)+\eta\le 2\eta.
\end{equation}
The second term of the right hand side of \eqref{eq:cv_conv3} can be bounded similarly. Therefore, $|P^*(V^I_n(\theta'_n,c)\ne \emptyset)-	\Pr(\mathfrak{W}(c)\ne\emptyset)|\to 0$ with probability (under $P_n$) approaching 1. This establishes the first claim.


(ii) 
By Part (i), for $c>0$, we have
