P^*_n(V^I_n(\theta'_n,c)\ne \emptyset)-	\mathrm{Pr}(\mathfrak{W}(c)\ne\emptyset)\to 0.	\label{eq:cv_conv2_1}
\end{align}
Fix $c>0$, and set
 \begin{align}
 g_{j} =\left\{ \begin{array}{lll}
  c - \mathbb{Z}_j, &  j=1,\dots,J,\\
  1, &  j=J+1,\dots,J+2d,\\
 0, & j=J+2d+1,J+2d+2.
 	\end{array} 
 	\right. \label{eq:cv_conv2_2}
 \end{align}
Mimic the argument following \eqref{eq:int1}. Then, this yields
\begin{align}
 \left\vert \mathrm{Pr}\left(\mathfrak{W}(c)\neq \emptyset \right)-\mathrm{Pr}\left(\mathfrak{W}(c-\delta)\neq \emptyset \right)\right\vert = \mathrm{Pr}\left(\{\mathfrak{W}(c)\neq \emptyset\} \cap  \{\mathfrak{W}(c-\delta)=\emptyset\}\right)\le\eta,\label{eq:cv_conv2_3a}\\
 \left\vert \mathrm{Pr}\left(\mathfrak{W}(c+\delta)\neq \emptyset \right)-\mathrm{Pr}\left(\mathfrak{W}(c)\neq \emptyset \right)\right\vert = \mathrm{Pr}\left(\{\mathfrak{W}(c+\delta)\neq \emptyset\} \cap  \{\mathfrak{W}(c)=\emptyset\}\right)\le \eta,\label{eq:cv_conv2_3b}
\end{align}
which therefore ensures that $c\mapsto \mathrm{Pr}(\mathfrak{W}(c)\ne\emptyset)$ is continuous at $c>0$.

Next, we show $c\mapsto\mathrm{Pr}\left(\mathfrak{W}(c)\neq \emptyset \right)$ is strictly increasing at any $c>0$.
For this, consider $c>0$ and $c-\delta>0$ for $\delta>0$. 
Define the $J$ vector $e$ to have elements $e_j = c - \mathbb{Z}_j,~j=1,\dots,J$. Suppose for simplicity that $\mathcal{J}^*$ contains the first $J^*$ inequality constraints. Let $e^{[1:J^*]}$ denote the subvector of $e$ that only contains elements corresponding to $j \in \mathcal{J}^*$, define $D^{[1:J^*,:]}$ correspondingly, and write 
\begin{align}
K=\left[ 
\begin{array}{c}
D^{[1:J^*,:]} \\ 
I_{d} \\ 
-I_{d} \\ 
p^{\prime } \\ 
-p^{\prime }
\end{array}
\right] ,~g=\left[ 
\begin{array}{c}
e^{[1:J^*]} \\ 
\rho \cdot \mathbf{1}_{d} \\ 
\rho \cdot \mathbf{1}_{d} \\ 
0 \\ 
0
\end{array}
\right] ,~\tau =\left[ 
\begin{array}{c}
\mathbf{1}_{J^*} \\ 
\mathbf{0}_{d} \\ 
\mathbf{0}_{d} \\ 
0 \\ 
0
\end{array}
\right] .\label{eq:Kgtau}
\end{align}

By Farkas' lemma \citep[][Theorem 22.1]{Rockafellar1970a}  and arguing as in \eqref{eq:int4},
\begin{align}
\mathrm{Pr}\left(\{\mathfrak{W}(c)\neq \emptyset\} \cap  \{\mathfrak{W}(c-\delta)=\emptyset\}\right)=
\mathrm{Pr}\left(\{\mu'g\ge0,\forall\mu\in\mathcal M\}\cap \{\mu'(g-\delta\tau)<0,\exists\mu\in\mathcal M\}\right),\label{eq:cv_conv3_1}
\end{align}
where $\mathcal M=\{\mu\in\mathbb R^{J^*+2d+2}_+:\mu'K=0\}.$
By Minkowski-Weyl's theorem \citep[][Theorem 3.52]{Rockafellar_Wets2005aBK}, there exists $\{\nu^t\in\mathcal M,t=1,\cdots,T\}$, for which one may write
\begin{align}
\mathcal M=\{\mu:\mu=b\sum_{t=1}^Ta_t\nu^t,b>0,a_t\ge0,\sum_{t=1}^Ta_t=1\}.\label{eq:cv_conv3_2}
\end{align}
This implies
\begin{align}
\mu'g\ge0,~\forall\mu\in\mathcal M&~\Leftrightarrow~\nu^{t}{}'g\ge0, ~\forall t\in\{1,\cdots,T\}\label{eq:cv_conv3_3a}\\
\mu'(g-\delta\tau)<0,~\exists\mu\in\mathcal M&~\Leftrightarrow~\nu^{t}{}'g<\delta\nu^{t}{}'\tau,~\exists t\in\{1,\cdots,T\}.\label{eq:cv_conv3_3b}
\end{align}
Hence,
\begin{align}
\mathrm{Pr}\left(\{\mu'g\ge0,\forall\mu\in\mathcal M\}\cap \{\mu'(g-\delta\tau)<0,\exists\mu\in\mathcal M\}\right)&=\textrm{Pr}\left(0\le \nu^{s}{}'g,~0\le \nu^{t}{}'g<\delta\nu^{t}{}'\tau,~\forall s,\exists t\right)\label{eq:cv_conv3_4}
\end{align}
Note that by \eqref{eq:Kgtau}, for each $s\in\{1,\cdots,T\},$
\begin{align}
\nu^{s}{}'g&=\nu^{s,[1:J^*]}{}'(c1_{\mathcal J^*}-\mathbb{Z}_{\mathcal J^*})+\rho\sum_{j=J^*+1}^{J^*+2d}\nu^{s,[j]},\label{eq:cv_conv3_5a}	\\
\nu^{s}{}'\tau&=\sum_{j=1}^{J^*}\nu^{s,[j]}.\label{eq:cv_conv3_5b}
\end{align}
For each $s\in\{1,\cdots,T\}$, let
\begin{align}
h^U_s &\equiv c\sum_{j=1}^{J^*}\nu^{s,[j]}+\rho\sum_{j=J^*+1}^{J^*+2d}\nu^{s,[j]}\label{eq:cv_conv3_6a}\\
h^L_s &\equiv (c-\delta)\sum_{j=1}^{J^*}\nu^{s,[j]},\label{eq:cv_conv3_6b}
\end{align}
where $0\le h_s^L<h_s^U$ for all $s\in\{1,\cdots,T\}$ due to $0<c-\delta<c$ and $\nu^s\in\mathbb R^{J^*+2d+2}_+$.
One may therefore rewrite the probability on the right hand side of \eqref{eq:cv_conv3_4} as
\begin{equation}
\textrm{Pr}\left(0\le \nu^{s}{}'g,~0\le \nu^{t}{}'g<\delta\nu^{t}{}'\tau,~\forall s,\exists t\right)
=\textrm{Pr}\left(\nu^{s,[1:J^*]}{}'\mathbb{Z}_{\mathcal J^*}\le h^U_s, h_t^L<\nu^{t,[1:J^*]}{}'\mathbb{Z}_{\mathcal J^*} \le h_t^U~\forall s,\exists t\right)>0,\label{eq:cv_conv3_7}
\end{equation}
where the last inequality follows because $\mathbb{Z}_{\mathcal J^*}$'s correlation matrix $\Omega$ has an eigenvalue bounded away from 0 by Assumption \ref{as:correlation}.
By \eqref{eq:cv_conv3_1}, \eqref{eq:cv_conv3_4}, and \eqref{eq:cv_conv3_7}, $c\mapsto\mathrm{Pr}\left(\mathfrak{W}(c)\neq \emptyset \right)$ is strictly increasing at any $c>0$.

Suppose that $c_{\pi^*}>0$, then arguing as in Lemma 5.(i) of \citet{Andrews:2010aa}, we obtain $c^I_n(\theta'_n)\stackrel{P_n}{\to}c_{\pi^*}$.


(iii) Begin with observing that one can equivalently express $\hat{c}_n$ (originally defined in \eqref{eq:def:c_hat}) as  $\hat{c}_n(\theta)= \inf\{c\in\mathbb{R}_+:P^*_n(V^b_n(\theta,c)\neq \emptyset) \ge 1-\alpha\}$. 

Suppose first that Assumption \ref{as:correlation}-\ref{as:correlation_base} holds. In this case, there are no paired inequalities, and $V^I_n$ differs from $V_n^b$ only in terms of the function $\varphi^*_j$ in \eqref{eq:greedy_gms} used in place of the GMS function $\varphi_j$. In particular, $\varphi^*_j(\xi)\le \varphi_j(\xi)$ for any $j$ and $\xi$, and therefore $\hat c_n(\theta_n)\ge c^{I}_n(\theta_n)$ by construction.

Next, suppose  Assumption \ref{as:correlation}-\ref{as:correlation_pair} holds and $V_n^I(\theta'_n,c)$ is defined with hard threshold GMS, i.e. with GMS function $\varphi^1$ in AS. The only case that might create concern is one in which
\begin{align}
\pi_{1,j}\in [-1,0)	~&\mathrm{and}~ \pi_{1,j+R_1}=0.
\end{align} 
In this case, only the $j+R_1$-th inequality binds in the limit, but with probability approaching $1$, GMS selects both of the pair. Therefore, we have
\begin{align}
\pi^*_{1,j}=-\infty, ~&\mathrm{and}~
\pi^*_{1,j+R_1}=0,\\
\varphi_j(\hat{\xi}_{n,j}(\theta'_n))=0, ~&\mathrm{and}~
\varphi_{j+R_1}(\hat{\xi}_{n,j+R_1}(\theta'_n))=0,
\end{align}
so that in $V_n^I(\theta'_n,c)$, inequality $j+R_1$, which is
\begin{align}
\mathbb G^b_{n,j+R_1}(\theta'_n)+\rho \hat D_{n,j+R_1}(\theta'_n)\lambda \le c,
\end{align}
is replaced with inequality
\begin{align}
-\mathbb G^b_{n,j}(\theta'_n)-\rho \hat D_{n,j}(\theta'_n)\lambda \le c,
\end{align}
as explained in Section \ref{sec:AssRes}. In this case, $\hat c_n(\theta_n)\ge c^{I}_n(\theta_n)$ is not guaranteed in finite sample. However, let $v^{IP}_n$ be as in \eqref{eq:vIj_var} but replacing  $j+R_1$-th component $\mathbb G^b_{n,j+R_1}(\theta_n)+\hat{D}_{n,j+R_1}(\theta_n)\lambda+\varphi^*_{j+R_1}(\hat{\xi}_{n,j+R_1}(\theta_n))$ with $-\mathbb G^b_{n,j}(\theta_n)-\hat{D}_{n,j}(\theta_n)\lambda-\varphi^*_j(\hat{\xi}_{n,j}(\theta_n)).$ Define $V^{IP}_n$ as in \eqref{eq:VIn} but replacing $v^I_n$ with $v^{IP}_n$. Define $c^{IP}_n(\theta_n)\equiv \inf\{c\in\mathbb{R}_+:P^*(V^{IP}_n(\theta_n,c))\ge 1-\alpha\}$. By construction, $\hat c_n(\theta'_n)\ge c^{IP}_n(\theta'_n)$ for any $\theta'_n\in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$. Therefore, it suffices to show that $c_n^{IP}(\theta'_n)-c_n^I(\theta'_n)\stackrel{P_n}{\to}0$.
For this, note that Lemma \ref{lem:pair}-(3) establishes 
\begin{align}
\sup_{\lambda\in B^d_{n,\rho}}\| \mathbb G^b_{n,j+R_1}(\theta'_n)+\rho \hat D_{n,j+R_1}(\theta'_n)\lambda+\mathbb G^b_{n,j}(\theta'_n)+\rho \hat D_{n,j}(\theta'_n)\lambda \| =o_{P^*}(1),\label{eq:dif_to_zeroCT}
\end{align}
for almost all sample paths $\{X_i\}_{i=1}^\infty.$  Therefore, replacing the $j+R_1$-th inequality with the $j$-th inequality in $V^{IP}_n$ is asymptotically negligible. Mimicking the arguments in Parts (i) and (ii) then yields
\begin{align}
	c^{IP}_n(\theta'_n)\stackrel{P_n}{\to}c_{\pi^*}.
\end{align}
This therefore ensures $c_n^{IP}(\theta'_n)-c_n^I(\theta'_n)\stackrel{P_n}{\to}0$.


If the set $V^I_n(\theta'_n,c)$ is defined with a GMS function satisfying Assumption \ref{as:GMS} and continuous in its argument, we can mimic the above argument using the replacements in \eqref{eq:paired_bind_Lboot_smooth}-\eqref{eq:paired_bind_Uboot_smooth} with $\hat\mu_{n,j+R_1}$ as defined in \eqref{eq:mu_hat_j} and $\hat\mu_{n,j}(\theta'_n)$ as in \eqref{eq:mu_hat_j_pl_J11}. Then when both $\pi_j \in (-\infty,0]$ and $\pi_{j+R_1}\in (-\infty,0]$ we have:
\begin{align}
\Delta(\mu,\hat{\mu})\equiv\Big\Vert  &\hat\mu_{n,j}(\theta'_n)\{\mathbb{G}_{n,j}^{b}(\theta'_n)+\rho \hat{D}
_{n,j}(\theta'_n)\lambda\} - \hat\mu_{n,j+R_1}(\theta'_n)\{\mathbb{G}_{n,j+R_1}^{b}(\theta'_n)+\rho \hat{D}
_{n,j+R_1}(\theta'_n)\lambda\}  \notag\\
-&\mu_j(\theta'_n)\{\mathbb{G}_{n,j}^{b}(\theta'_n)+\rho \hat{D}
_{n,j}(\theta'_n)\lambda\} + \mu_{j+R_1}(\theta'_n)\{\mathbb{G}_{n,j+R_1}^{b}(\theta'_n)+\rho \hat{D}
