We first show \eqref{eq:emptiness1}. If $\mathcal{J}^*=\emptyset$, with $\mathcal{J}^*$ as defined in \eqref{eq:Jstar}, then the result is immediate. Assume then that $\mathcal{J}^* \neq \emptyset$. Any inequality indexed by $j \notin \mathcal{J}^*$ is satisfied with probability approaching one by similar arguments as in \eqref{eq:pi_star_gamma_vanishes} (both with $c$ and with $c-\delta$). Hence, one could argue for sets $\mathfrak W(c),\mathfrak W^{-\delta}(c)$ defined as in equations \eqref{eq:set_W_Lpop} and \eqref{eq:Wdelta} but with $j \in \mathcal{J}^*$. To keep the notation simple, below we argue as if all $j=1,\dots,J$ belong to $\mathcal{J}^*$.
Let $c \ge 0$ be given. Let $g$ be a $J+2d+2$ vector with entries
\begin{align}
\label{eq:int1}
g_j =\left\{ \begin{array}{lll}
 c - \mathbb{Z}_j, &  j=1,\dots,J,\\
1, &  j=J+1,\dots,J+2d,\\
0, & j=J+2d+1,J+2d+2,
	\end{array} 
	\right. 
\end{align}
recalling that $\pi_{1,j}^*=0$ for $j=J_1+1,\cdots,J$. Let $\tau$ be a $(J+2d+2)$ vector with entries
	\begin{align}
	\label{eq:tau}
	\tau_j = \left\{ \begin{array}{ll}
	1, & j =1,\dots,J_1, \\ 
	0, & j =J_1+1,\dots,J+2d+2.
	\end{array} 
	\right. 
	\end{align}
	Then we can express the sets of interest as
\begin{align}
\mathfrak W(c) &= \{\lambda: K\lambda \le g\},\label{eq:W:matrix}\\
\mathfrak W^{-\delta}(c)&= \{\lambda: K\lambda \le g-\delta \tau\}.\label{eq:W_delta:matrix}
\end{align}
By Farkas' Lemma, e.g. \citet[Theorem 22.1]{Rockafellar1970a}, a solution to the system of linear inequalities in \eqref{eq:W:matrix} exists if and only if for all $\mu \in \mathbb{R}^{J+2d+2}_+$ such that $\mu^{\prime}K=0$, one has $\mu^{\prime}g \ge 0$. Similarly, a solution to the system of linear inequalities in \eqref{eq:W_delta:matrix}
exists if and only if for all $\mu \in \mathbb{R}^{J+2d+2}$ such that $\mu^{\prime}K=0$, one has $\mu^{\prime}(g-\delta \tau) \ge 0$. Define
\begin{align}
	\mathcal M\equiv \{ \mu\in\mathbb R^{J+2d+2}_+:\mu' K=0\}.\label{eq:int3}
\end{align}
Then, one may write
\begin{align}
	&~\Pr(\{\mathfrak W(c)\ne \emptyset \} \cap \{W^{-\delta}(\theta_n^\prime,c)= \emptyset \} )\notag\\

=&~\Pr(\{\mu'g\ge 0, \forall\mu\in \mathcal M\}\cap \{\mu'(g-\delta \tau)< 0, \exists\mu\in \mathcal M\})\notag \\
= &~\Pr(\{\mu'g\ge 0, \forall\mu\in \mathcal M\}\cap\{ \mu'g< \delta\mu'\tau, \exists\mu\in \mathcal M\})
\label{eq:int4}.
\end{align}
Note that the set $\mathcal M$ is a non-stochastic polyhedral cone which may change with $n$. By Minkowski-Weyl's theorem (see, e.g. \citet[Theorem 3.52]{Rockafellar_Wets2005aBK}), for each $n$ there exist $\{\nu^t\in \mathcal M,t=1,\cdots, T\}$, with $T<\infty$ a constant that depends only on $J$ and $d$, such that
any $\mu\in\mathcal M$ can be represented as



\begin{align}
\mu=b \sum_{t=1}^T a_t\nu^t,\label{eq:int5}
\end{align}
where $b>0$ and $a_t\ge 0, ~t=1,\dots,T, ~\sum_{t=1}^T a_t=1$. Hence, if $\mu\in\mathcal M$ satisfies $ \mu'g< \delta\mu'\tau$, denoting $\nu^{t \prime}$ the transpose of vector $\nu^t$, we have
\begin{align}
\sum_{t=1}^T	a_t\nu^{t \prime}g<\delta\sum_{t=1}^T	a_t\nu^{t \prime}\tau.\label{eq:int6}
\end{align}
However, due to $a_t\ge 0,\forall t$ and $\nu^t\in\mathcal M$, this means  $\nu^{t\prime}g< \delta\nu^{t \prime}\tau$ for some $t\in\{1,\dots,T\}.$ Furthermore, since $\nu^t\in\mathcal M$, we have $0\le \nu^{t\prime}g$.
Therefore,
\begin{multline}
{\Pr}\left(\{\mu'g\ge 0, \forall\mu\in \mathcal M\}\cap\{\mu'g< \delta \mu^\prime \tau, \exists\mu\in \mathcal M\}\right)\\
	\le {\Pr}\left(0\le\nu^{t\prime}g< \delta\nu^{t\prime}\tau,\exists t\in\{1,\cdots,T\}\right)
	\le \sum_{t=1}^T {\Pr}\left(0\le\nu^{t\prime}g< \delta\nu^{t\prime}\tau \right).\label{eq:int7}
	\end{multline}

\noindent \textbf{Case 1.} Consider first any $t =1,\dots,T$ such that $\nu^t$ assigns positive weight only to constraints in $\{J+1,\dots,J+2d+2\}$. Then
\begin{align*}
\nu^{t \prime} g&=\sum_{j=J+1}^{J+2d}\nu^t_{j},\\
\delta\nu^{t \prime} \tau &=\delta\sum_{j=J+1}^{J+2d+2}\nu^t_{j} \tau_j=0,
\end{align*}
where the last equality follows by \eqref{eq:tau}.
Therefore 
${\Pr}\left(0\le\nu^{t\prime}g< \delta\nu^{t\prime}\tau \right)=0$.

\noindent \textbf{Case 2.} Consider now any $t = 1,\dots,T$ such that $\nu^t$ assigns positive weight also to constraints in $\{1,\dots,J\}$. 
Recall that indices $j=J_1+1,\dots,J_1+2J_2$ correspond to moment equalities, each of which is written as two moment inequalities, therefore yielding a total of $2J_2$ inequalities with $D_{j+J_2} = - D_{j}$ for $j =J_1+1,\dots,J_1+J_2$, and:
\begin{equation}
g = \left\{\begin{array}{ll}
 c - \mathbb{Z}_j & j =J_1+1,\dots,J_1+J_2, \\
 c + \mathbb{Z}_{j-J_2} & j =J_1+J_2+1,\dots,J.
\end{array} \label{eq:int8}
\right.
\end{equation}
For each $\nu^t$, \eqref{eq:int8} implies
\begin{align}
\sum_{j=J_1+1}^{J_1+2J_2} \nu^t_j g_j &=c\sum_{j=J_1+1}^{J_1+2J_2} \nu^t_j + \sum_{j=J_1+1}^{J_1+J_2} (\nu^t_j-\nu^t_{j+J_2})\mathbb{Z}_j.\label{eq:int9}
\end{align}
For each $j=1,\cdots,J_1+J_2$, define
\begin{align}
	\tilde\nu^t_j\equiv\begin{cases}
	\nu^t_j&j=1,\cdots, J_1\\
	\nu^t_j-\nu^t_{j+J_2}&j=J_1+1,\cdots,J_1+J_2.
	\end{cases}.\label{eq:int10}
\end{align}
We then let $\tilde\nu^t\equiv(\tilde\nu^t_{n,1},\cdots,\tilde \nu^t_{n,J_1+J_2})'$ and have
\begin{align}
\nu^{t \prime}g=\sum_{j=1}^{J_1+J_2}\tilde\nu^t_j\mathbb{Z}_j+c\sum_{j=1}^J\nu^t_j+\sum_{j=J+1}^{J+2d}\nu^t_j.\label{eq:int11}
\end{align}

\noindent \textbf{Case 2-a.} Suppose  $\tilde\nu^t\ne 0$. Then, by \eqref{eq:int11}, $\frac{\nu^{t \prime}g}{\nu^{t \prime}\tau}$ is a normal random variable  with variance $(\tilde\nu^{t \prime}\tau)^{-2}\tilde\nu'^t\Omega\tilde\nu^t$.   By Assumption \ref{as:correlation}, there exists a constant $\omega>0$ such that the smallest eigenvalue of $\Omega$ is bounded from below by $\omega$ for all $\theta_n^\prime$.
