\[|Cov_{P_n}(m_j(X_i,\theta^\prime_n),t_j(X_i,\theta^\prime_n))/\sigma^2_{P_n,j}(\theta^\prime_n)| \le (Var_{P_n}(t_j(X_i,\theta^\prime_n)))^{1/2}/\sigma_{P_n,j}(\theta^\prime_n),\]
