Second, using Assumption \ref{as:momP_KMS}, we have that
\begin{align}
\frac{E_{P_n}(m_{j+R_1}(X,\theta^\prime_n+r_n))}{\sigma_{P_n,j+R_1}(\theta^\prime_n+r_n)} = \frac{E_{P_n}(m_{j+R_1}(X,\theta^\prime_n))}{\sigma_{P_n,j+R_1}(\theta^\prime_n)}+D_{P_n,j+R_1}(\tilde{\theta}_n) r_n = O_\mathcal{P}(\frac{\kappa_n}{\sqrt n})+O_\mathcal{P}(\frac{\rho \kappa_n^2}{\sqrt n}).\label{eq:pair_prod2}
\end{align}
The product of \eqref{eq:pair_prod1} and \eqref{eq:pair_prod2} is therefore $o_\mathcal{P}(\frac{\rho \kappa_n^2}{\sqrt n})$ and \eqref{eq:grad_lhs_neg} follows.

To conclude the argument, note that for $n$ large enough, $m_{j+R_1}(X,\theta^\prime_n+r_n) \le - m_j(X,\theta^\prime_n+r_n)$ $a.s.$ because for any $\theta_n \in \Theta_I(P_n)$ and $\theta^\prime_n \in (\theta_n +\rho /\sqrt{n} B^d)\cap \Theta$ for $n$ large enough, $\theta^\prime_n+r_n \in \Theta^\epsilon$ and Assumption \ref{as:correlation}-\ref{as:correlation_pair} applies. Therefore, there exists $N \in \mathbb{N}$ such that for all $n \ge N$, the left hand side in \eqref{eq:grad_conc} is strictly less than the right hand side, yielding a contradiction.

\label{lem:eta_conv}
	Suppose Assumptions \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1} hold. For each $\theta\in\Theta$, let $\eta_{n,j}(\theta)=\sigma_{P,j}(\theta)/\hat\sigma_{n,j}(\theta)-1$. Then, (i) for each $j=1,\dots,J_1+J_2$
\begin{align}
	\inf_{P\in\mathcal P}P
	\Big(\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|
	\to 0\Big)=1.
\end{align}	
(ii)
For any $j=1,\dots,R_1$ 
let
\begin{align}
\hat \sigma_{n,j}^M(\theta)=\hat \sigma_{n,j+R_1}^M(\theta)\equiv\hat \mu_{n,j}(\theta)\hat\sigma_{n,j}(\theta)+(1-\hat \mu_{n,j}(\theta))\hat\sigma_{n,j+R_1}(\theta). \label{eq:def_hat_sigma_M}
\end{align} 
Let $(P_n,\theta_n)$ be a sequence such that $P_n\in\mathcal P$, $\theta_n\in\Theta$ for all $n$, and $\kappa_n^{-1}\sqrt{n}\gamma_{1,P_n,j}(\theta_n) \to \pi_{1j} \in \mathbb{R}_{[-\infty]}$. Let $\mathcal J^*$ be defined as in \eqref{eq:Jstar}.
Then, for any $\eta>0$, there exists $N\in\mathbb N$ such that
\begin{align}
	P_n\Big(\max_{j\in(\mathcal R_1\cup \mathcal R_2)\cap\mathcal J^*}\Big|\frac{\sigma_{P_n,j}(\theta_n)}{\hat\sigma^M_{n,j}(\theta_n)}-1\Big|>\eta\Big)<\eta
\end{align}
for all  $n\ge N$.

We first show that, for any $\epsilon>0$ and for any $j=1,\dots,J_1+J_2$,
\begin{align}
\inf_{P\in\mathcal P}P
\Big(\sup_{m\ge n}\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}(\theta)}{\sigma_{P,j}(\theta)}-1\Big|\le \epsilon\Big)\to 1.	\label{eq:ec0}
\end{align}
For this, define the following sets:
	\begin{align}
		\mathcal{M}_j&\equiv\{m_j(\cdot,\theta)/\sigma_{P,j}(\theta):\theta\in\Theta,P\in\mathcal P\}\label{eq:ec1}\\
		\mathcal{S}_j&\equiv\{(m_j(\cdot,\theta)/\sigma_{P,j}(\theta))^2:\theta\in\Theta,P\in\mathcal P\}.\label{eq:ec2}
	\end{align}
By Assumptions \ref{as:momP_AS}-(a), \ref{as:momP_AS} (iv), \ref{as:bcs1} (i), (iii),  and arguing as in the proof of Lemma D.2.2 (and D.2.1) in \citet{BCS14_misp}, it follows that $\mathcal{S}_j$ and $\mathcal{M}_j$ are Glivenko-Cantelli (GC) classes uniformly in $P\in\mathcal P$ \citep[in the sense of][page 167]{Vaart_Wellner2000aBK}.   

Therefore, for any $\epsilon>0$, 
\begin{align}
\inf_{P\in\mathcal P}&P\Big(	\sup_{m\ge n}\sup_{\theta\in\Theta}\Big|\frac{n^{-1}\sum_{i=1}^n m_{j}(X_i,\theta)^2}{\sigma^2_{P,j}(\theta)}-\frac{E_P[m_j(X,\theta)^2]}{\sigma^2_{P,j}(\theta)}\Big|\le \epsilon\Big)\to 1\label{eq:ec3}\\	
\inf_{P\in\mathcal P}&P\Big(\sup_{m\ge n}\sup_{\theta\in\Theta}\Big|\frac{\bar m_{n,j}(\theta)-E_P[m_j(X,\theta)]}{\sigma_{P,j}(\theta)}\Big|\le \epsilon\Big)\to 1.\label{eq:ec4}
\end{align}
Note that, by  Assumption \ref{as:momP_AS} (iv), $|E_P[m_j(X,\theta)]/\sigma_{P,j}(\theta)|\le M$  for some constant $M>0$ that does not depend on $P$ and $(x^2-y^2)\le |x+y||x-y|\le 2M|x-y|$ for all $x,y\in [-M,M]$. By \eqref{eq:ec4},   for any $\epsilon>0$, it follows that
\begin{align}
	\inf_{P\in\mathcal P}P\Big(\sup_{m\ge n}\sup_{\theta\in\Theta}\Big|\frac{\bar m_{n,j}(\theta)^2-E_P[m_j(X,\theta)]^2}{\sigma^2_{P,j}(\theta)}\Big|\le \epsilon\Big)\to 1.\label{eq:ec5}
\end{align}

By the uniform continuity of $x\mapsto \sqrt x$ on $\mathbb R_+$, for any $\epsilon>0$, there is a constant $\eta>0$ such that
\begin{align}
\Big|\frac{\hat\sigma^2_{n,j}(\theta)}{\sigma^2_{P,j}(\theta)}-1\Big|\le \eta~\Rightarrow \Big|\frac{\hat\sigma_{n,j}(\theta)}{\sigma_{P,j}(\theta)}-1\Big|\le \epsilon.\label{eq:ec6}
\end{align}	
By the definition of $\sigma^2_{P,j}(\theta)$ and the triangle inequality,
\begin{align}
\Big|\frac{\hat\sigma^2_{n,j}(\theta)}{\sigma^2_{P,j}(\theta)}-1\Big|
\le \Big|\frac{n^{-1}\sum_{i=1}^n m(X_i,\theta)^2-E[m_j(X_i,\theta)^2]}{\sigma^2_{P,j}(\theta)}	\Big|+\Big|\frac{\bar m_{n,j}(\theta)^2-E[m_j(X_i,\theta)]^2}{\sigma^2_{P,j}(\theta)}\Big|.\label{eq:ec7}
\end{align}
By \eqref{eq:ec6}-\eqref{eq:ec7}, bounding each of the terms on the right hand side of \eqref{eq:ec7} by $\eta/2$ implies $|\hat\sigma_{n,j}(\theta)/\sigma_{P,j}(\theta)-1|\le \epsilon$.
This, together with \eqref{eq:ec3} and \eqref{eq:ec5}, ensures that, for any $\epsilon>0$, \eqref{eq:ec0} holds.

Note that $|\hat\sigma_{n,j}(\theta)/\sigma_{P,j}(\theta)-1|\le \epsilon$ implies $\hat\sigma_{n,j}(\theta)>0$, and argue as in the proof of Lemma D.2.4 in \citet{BCS14_misp}  to conclude that
\begin{align}
	\inf_{P\in\mathcal P}P
	\Big(\sup_{m\ge n}\sup_{\theta\in\Theta}\Big|\frac{\sigma_{P,j}(\theta)}{\hat\sigma_{n,j}(\theta)}-1\Big|\le \epsilon\Big)\to 1.\label{eq:ec8}
\end{align}
Finally, recall that $\eta_{n,j}(\theta)=\sigma_{P,j}(\theta)/\hat\sigma_{n,j}(\theta)-1$ and note that for any $\epsilon>0$, 
\begin{align}
1&=\lim_{n\to\infty}\inf_{P\in \mathcal P}P
\Big(\sup_{m\ge n}\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le \epsilon\Big)\notag\\
&\le 	\inf_{P\in \mathcal P}\lim_{n\to\infty}P
\Big(\bigcap_{m\ge n}\big\{\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le \epsilon\big\}\Big)\notag\\
&=\inf_{P\in \mathcal P}P
\Big(\lim_{n\to\infty}\bigcap_{m\ge n}\{\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le \epsilon\big\}\Big)\notag\\
&=\inf_{P\in\mathcal P}P
\Big(\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le \epsilon, \text{ for almost all } n\Big),\label{eq:ec9}
\end{align}
where the second equality is due to the continuity of probability with respect to monotone sequences.
 Therefore, the first conclusion of the lemma follows.

