	&=(1+o_{ P_n}(1))\hat\sigma_{n,j}(\theta_n)+(1-\hat \mu_{n,j}(\theta_n))O_{P_n}(\hat\sigma_{n,j}(\theta_n)),\label{eq:sigconv2}
\end{align}
where the second equality follows from \eqref{eq:mulim1} and the fact that
\begin{multline}
