=\Big(\hat\sigma_{n,j}^2(\theta_n)+O_{P_n}(\hat\sigma_{n,j}(\theta_n))+O_{P_n}(1)\Big)^{1/2}=O_{P_n}(\hat\sigma_{n,j}(\theta_n)),
\end{multline}
where the second equality follows from,  $Var_{P_n}(t_j(X_i,\theta))$ being bounded by Assumption \ref{as:correlation}-(II) and
\begin{align}
	&\widehat{Var}_{n}(t_j(X_i,\theta))=Var_{P_n}(t_j(X_i,\theta))+o_{P_n}(1)\\
	&\widehat{Cov}_n(m_j(X_i,\theta),t_j(X_i,\theta))\le \hat \sigma_{n,j}(\theta_n)\widehat{Var}_{n}(t_j(X_i,\theta))^{1/2},
\end{align}
where the last inequality is due to the Cauchy-Schwarz inequality.

 Therefore,
\begin{align}
