\label{lem:se_rate}
	(i) Let $\mathcal M_P\equiv\{f:\mathcal X\to\mathbb R:f(\cdot)=\sigma_{P,j}(\theta)^{-1}m_j(\cdot,\theta),\theta\in\Theta,j=1,\cdots,J\}$ and let $F$ be its envelope. Suppose that (i) there exist constants $K,v>0$ that do not depend on $P$ such that
	\begin{align}
	\sup_Q N(\epsilon\|F\|_{L^2_Q},\mathcal M_P,L^2_Q)\le K\epsilon^{-v}	,~0<\epsilon<1,\label{eq:as_euclidean}
	\end{align}
	where the supremum is taken over all discrete distributions; (ii) There exists a positive constant $\gamma>0$ such that 
	\begin{align}
	\|(\theta_1,\tilde\theta_1)-(\theta_2,\tilde\theta_2)\|\le\delta~~\Rightarrow~~\sup_{P\in\mathcal P}\|Q_P(\theta_1,\tilde\theta_1)-Q_P(\theta_2,\tilde\theta_2)\|\le M\delta^\gamma.\label{eq:correl_holder}
	\end{align}
	Let $\delta_n$ be a positive sequence tending to 0 and let $\epsilon_n$ be a positive sequence such that $\epsilon_n/|\delta_n^\gamma\ln\delta_n|\to\infty$ as $n\to\infty$.
		Then, \begin{align}
\sup_{P\in\mathcal P}P\left(\sup_{\|\theta-\theta'\|\le \delta_n}\|\mathbb G_n(\theta)-\mathbb G_n(\theta'))\|>\epsilon_n \right)=o(1).\label{eq:sr1}
\end{align}
Further,
\begin{align}
\lim_{n\to\infty}P^*_n \left(\sup_{\|\theta-\theta'\|\le \delta_n}\|\mathfrak G^b_{n}(\theta)-\mathfrak G^b_{n}(\theta'))\|>\epsilon_n|\{X_i\}_{i=1}^\infty \right)=0.	
\end{align}
for almost all sample paths $\{X_i\}_{i=1}^\infty$ uniformly in $P\in \mathcal P$.

For the first conclusion of the lemma, it suffices to show that there is a sequence $\{\epsilon_n\}$ such that, uniformly in $P$:
\begin{align}
P\left(\sup_{\|\theta-\theta'\|\le \delta_n}\max_{j=1,\cdots,J}|\mathbb G_{n,j}(\theta)-\mathbb G_{n,j}(\theta')|>\epsilon_n \right)=o(1).
\end{align}
For this purpose, we mostly mimic the argument required to show the stochastic equicontinuity of empirical processes \citep[see e.g.][Ch.2.5]{Vaart_Wellner2000aBK}. 
Before doing so, note that, arguing as in the proof of Lemma D.1 (Part 1) in \citet{BCS14_misp}, one has
\begin{align}
\|\theta-\theta'\|\le \delta_n~~\Rightarrow~~  \varrho_P(\theta,\theta')\le \tilde\delta_n,	\label{eq:sr2}
\end{align}
where $\tilde\delta_n=O(\delta_n^\gamma)$ by assumption.
Define
\begin{align}
\mathcal M_{P,\tilde \delta_n}=\{\sigma_{P,j}(\theta)^{-1}m_j(\cdot,\theta)-\sigma_{P,j}(\theta')^{-1}m_j(\cdot,\theta')| \theta,\theta'\in\Theta,\varrho_P(\theta,\tilde\theta)<\tilde\delta_n,j=1,\cdots,J\}.	\label{eq:sr3}
\end{align}
Define $Z_n(\tilde\delta_n)\equiv \sup_{f\in\mathcal M_{\tilde\delta_n}}|\sqrt n(\mathbb P_n-P)f|.$ Then, by \eqref{eq:sr2}, one has
\begin{align}
P\Biggl(\sup_{\|\theta-\theta'\|\le \delta_n}\max_{j=1,\cdots,J}|\mathbb G_{n,j}(\theta)-\mathbb G_{n,j}(\theta'))|>\epsilon_n)\le P(Z_n(\tilde\delta_n)>\epsilon_n \Biggr).\label{eq:sr4}	
\end{align}
From here, we deal with the supremum of  empirical processes though symmetrization and an application of a maximal inequality.
By Markov's inequality and Lemma 2.3.1 (symmetrization lemma) in \citet{Vaart_Wellner2000aBK}, one has
\begin{align}
P(Z_n(\tilde\delta_n)>\epsilon_n)\le \frac{2}{\epsilon_n}E_{P\times P^W}\left[\sup_{f\in\mathcal M_{P,\tilde\delta_n}}\Bigl\vert\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X_i)\Bigr\vert\right],\label{eq:sr5}
\end{align}
where $\{W_i\}_{i=1}^n$ are i.i.d. Rademacher random variables independent of $\{X_i\}_{i=1}^\infty$ whose law is denoted by $P^W$. Now, fix the sample path $\{X_i\}_{i=1}^n$, and let $\hat P_n$ be the empirical distribution. By Hoeffding's inequality, the stochastic process $f\mapsto\{n^{-1/2}\sum_{i=1}^nW_if(X_i)\}$ is sub-Gaussian for the $L^2_{\hat P_n}$ seminorm $\|f\|_{L^2_{\hat P_n}}=(n^{-1}\sum_{i=1}^n f(X_i)^2)^{1/2}.$ By the maximal inequality (Corollary 2.2.8) and arguing as in the proof of Theorem 2.5.2 in in \citet{Vaart_Wellner2000aBK}, one then has
\begin{align}
	E_{P^W}\left[\sup_{f\in\mathcal M_{\tilde\delta_n}}\Bigl\vert\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X_i)\Bigr\vert \right]&\le K\int_0^{\tilde\delta_n}\sqrt{\ln N(\epsilon,\mathcal M_{P,\tilde\delta_n},L^2_{\hat P_n})}d\epsilon\notag\\
	&\le K\int_0^{\tilde\delta_n/\|F\|_{L^2_Q}}\sup_Q\sqrt{\ln N(\epsilon \|F\|_{L^2_Q},\mathcal M_P,L^2_Q)}d\epsilon\notag\\
	&\le K'\int_0^{\tilde\delta_n/\|F\|_{L^2_Q}}\sqrt{-v\ln\epsilon}d\epsilon,\label{eq:sr6}
\end{align}
for some $K'>0$, 
where the last inequality follows from \eqref{eq:as_euclidean}.
Note that $\sqrt{-\ln \epsilon}\le -\ln \epsilon$ for $\epsilon\le \tilde\delta_n/\|F\|_{L^2_Q}$ with $n$ sufficiently large. Hence, 
\begin{align}
E_{P^W}\left[\sup_{f\in\mathcal M_{\tilde\delta_n}}\Bigl\vert\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X_i)\Bigr\vert\right]&\le K'v^{1/2}\int_0^{\tilde\delta_n/\|F\|_{L^2_Q}} (-\ln\epsilon) d\epsilon 	=K'v^{1/2}(\tilde\delta_n-\tilde\delta_n\ln(\tilde\delta_n)).\label{eq:sr7}
\end{align}
By \eqref{eq:sr5} and taking expectations with respect to $P$ in \eqref{eq:sr7}, it follows that
\begin{align}
P(Z_n(\tilde\delta_n)>\epsilon_n)\le 2K'v^{1/2}(\tilde\delta_n-\tilde\delta_n\ln(\tilde\delta_n))/\epsilon_n=O(\delta_n^\gamma/\epsilon_n)+O(|\delta_n^\gamma\ln(\delta_n)|/\epsilon_n)=o(1),	\label{eq:sr8}
\end{align}
where the last equality follows from the rate condition on $\epsilon_n$. By \eqref{eq:sr4} and \eqref{eq:sr8}, conclude that the first claim of the lemma holds.

For the second claim, define $Z^*_n(\tilde\delta_n)\equiv \sup_{f\in\mathcal M_{\tilde\delta_n}}|\sqrt n(\hat P^*_n-\hat P_n)f|,$ where $\hat P^*_n$ is the empirical distribution of $\{X_i^b\}_{i=1}^n$. Then, by \eqref{eq:sr2}, one has
\begin{align}
P^*_n\left(\sup_{\|\theta-\theta'\|\le \delta_n}\max_{j=1,\cdots,J}|\mathfrak G^b_{n,j}(\theta)-\mathfrak G^b_{n,j}(\theta')|>\epsilon_n\Big|\{X_i\}_{i=1}^\infty\right)\le P^*_n\big(Z^*_n(\tilde\delta_n)>\epsilon_n\big|\{X_i\}_{i=1}^\infty\big).\label{eq:sr9}	
\end{align}
By Markov's inequality and Lemma 2.3.1 (symmetrization lemma) in \citet{Vaart_Wellner2000aBK}, one has
\begin{align}
P^*_n\big(Z^*_n(\tilde\delta_n)>\epsilon_n\big|\{X_i\}_{i=1}^\infty\big)&\le \frac{2}{\epsilon_n}E_{P^*_n\times P^W}\left[\sup_{f\in\mathcal M_{P,\tilde\delta_n}}\Big|\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X^b_i)\Big| \Bigg|\{X_i\}_{i=1}^\infty\right]\\
&=\frac{2}{\epsilon_n}E_{P^*_n}\left[E_{P^W}\left[\sup_{f\in\mathcal M_{P,\tilde\delta_n}}\Big| \frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X^b_i)\Big| \Bigg|\{X^b_i\},\{X_i\}_{i=1}^\infty\right]\Bigg|\{X_i\}_{i=1}^\infty\right],\label{eq:sr10}
\end{align}
where $\{W_i\}_{i=1}^n$ are i.i.d. Rademacher random variables independent of $\{X_i\}_{i=1}^\infty$ and $\{M_{n,i}\}_{i=1}^n$.
Argue as in \eqref{eq:sr5}-\eqref{eq:sr8}. Then, it follows that
\begin{align*}
P^*_n(Z^*_n(\tilde\delta_n)>\epsilon_n|\{X_i\}_{i=1}^\infty)=O(\delta_n^\gamma/\epsilon_n)+O(-\delta_n^\gamma\ln(\delta_n)/\epsilon_n)=o(1),
\end{align*}
 for almost all sample paths. Hence, the second claim of the lemma follows.

\begin{align}
	E_{P^W}\left[\sup_{f\in\mathcal M_{\tilde\delta_n}}\Bigl\vert\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X_i)\Bigr\vert \right]&\le K\int_0^{\tilde\delta_n}\sqrt{\ln N(\epsilon,\mathcal M_{P,\tilde\delta_n},L^2_{\hat P_n})}d\epsilon\notag\\
	&\le K\int_0^{\tilde\delta_n/\|F\|_{L^2_Q}}\sup_Q\sqrt{\ln N(\epsilon \|F\|_{L^2_Q},\mathcal M_P,L^2_Q)}d\epsilon\notag\\
	&\le K'\int_0^{\tilde\delta_n/\|F\|_{L^2_Q}}\sqrt{-v\ln\epsilon}d\epsilon,\label{eq:sr6}
\end{align}

\begin{align}
P^*_n\big(Z^*_n(\tilde\delta_n)>\epsilon_n\big|\{X_i\}_{i=1}^\infty\big)&\le \frac{2}{\epsilon_n}E_{P^*_n\times P^W}\left[\sup_{f\in\mathcal M_{P,\tilde\delta_n}}\Big|\frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X^b_i)\Big| \Bigg|\{X_i\}_{i=1}^\infty\right]\\
&=\frac{2}{\epsilon_n}E_{P^*_n}\left[E_{P^W}\left[\sup_{f\in\mathcal M_{P,\tilde\delta_n}}\Big| \frac{1}{\sqrt n}\sum_{i=1}^nW_i f(X^b_i)\Big| \Bigg|\{X^b_i\},\{X_i\}_{i=1}^\infty\right]\Bigg|\{X_i\}_{i=1}^\infty\right],\label{eq:sr10}
\end{align}

\label{lem:eta_rate}
Suppose Assumptions  \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1}  hold.
Let $\mathcal S_P\equiv\{f:\mathcal X\to\mathbb R:f(\cdot)=\sigma_{P,j}(\theta)^{-2}m_j^2(\cdot,\theta),\theta\in\Theta,j=1,\cdots,J\}$ and let $F$ be its envelope. 
(i) If $\mathcal S_P$ is Donsker and pre-Gaussian uniformly in $P\in\mathcal P$, then
\begin{align}
	\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|^*=O_{\mathcal P}(1/\sqrt n);
\end{align}	
(ii) If $|\sigma_{P,j}(\theta)^{-1}m_j(x,\theta)-\sigma_{P,j}(\theta')^{-1}m_j(x,\theta')|\le \bar M(x)\|\theta-\theta'\|$ with $E_P[\bar M(X)^{2}]<M$ for all $\theta,\theta'\in\Theta$, $x\in\mathcal X$, $j=1,\cdots,J$, and $P\in\mathcal P$,  then, for any $\eta>0$, there exists a constant $C>0$ such that
\begin{align}
\limsup_{n\to\infty}	\sup_{P\in\mathcal P}P\Big(\max_{j=1,\cdots,J}\sup_{\|\theta-\theta'\|<\delta}|\eta_{n,j}(\theta)-\eta_{n,j}(\theta')|>C\delta\Big)<\eta.
\end{align}

We show the claim by first showing that, for any $\delta>0$, there exist $M>0$ and $N\in\mathbb N$ such that
\begin{align}
\inf_{P\in\mathcal P}P^\infty\Big(\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}(\theta)}{\sigma_{P,j}(\theta)}-1\Big|\le M/\sqrt n\Big)\ge 1-\delta,~\forall n\ge N.\label{eq:ec10}
\end{align}
By Assumptions  \ref{as:momP_AS} (iv), \ref{as:bcs1} and Theorem 2.8.2 in \citet{Vaart_Wellner2000aBK},  $\mathcal{M}_P$ is a  Donsker class uniformly in $P\in\mathcal P$. 
By hypothesis, $\mathcal S_P$ is a  Donsker class uniformly in $P\in\mathcal P$. 

 Therefore, by the continuous mapping theorem, for any $\epsilon>0$, 
\begin{align}
&\Big|P\Big(	\sqrt n\sup_{\theta\in\Theta}\Big|\frac{n^{-1}\sum_{i=1}^n m_{j}(X_i,\theta)^2}{\sigma_{P,j}^2(\theta)}-\frac{E_P[m_j(X,\theta)^2]}{\sigma_{P,j}^2(\theta)}\Big|\le C_1\Big)-\text{Pr}(\sup_{\theta\in\Theta}|\mathbb H_{P,j}(\theta)|\le C_1)\Big|\le \epsilon \label{eq:ec11}\\	
&\Big|P\Big(\sqrt n\sup_{\theta\in\Theta}\Big|\frac{\bar m_{n,j}(\theta)-E_P[m_j(X,\theta)]}{\sigma_{P,j}(\theta)}\Big|\le C_2\Big)-\text{Pr}(\sup_{\theta\in\Theta}|\mathbb G_{P,j}(\theta)|\le C_2)\Big|\le \epsilon .\label{eq:ec12}
\end{align}
for $n$ sufficiently large uniformly in $P\in\mathcal P$, where $\mathbb H_{P,j}$ and $\mathbb G_{P,j}$ are tight Gaussian processes, and $C_1$ and $C_2$ are the continuity points of the distributions of $\sup_{\theta\in\Theta}|\mathbb H_{P,j}(\theta)|$ and $\sup_{\theta\in\Theta}|\mathbb G_{P,j}(\theta)|$ respectively.  As in the proof of Lemma \ref{lem:eta_conv} (i), bounding each term of the right hand side of \eqref{eq:ec7} by $C_1/\sqrt n$ and $C_2/\sqrt n$ implies that  $\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}^2(\theta)}{\sigma_{P,j}^2(\theta)}-1\Big|\le C/\sqrt n$ for some constant $C>0$.  Now choose $C_1>0$ and $C_2>0$ so that
\begin{align}
	\text{Pr}(\sup_{\theta\in\Theta}|\mathbb H_{P,j}(\theta)|\le C_1)> 1-\delta/3~\text{ and }~
	\text{Pr}(\sup_{\theta\in\Theta}|\mathbb G_{P,j}(\theta)|\le C_2)>1-\delta/3\label{eq:ec13}
\end{align}
and set $\epsilon>0$ sufficiently small so that $1-2\delta/3-2\epsilon\ge 1-\delta$. The existence of such continuity points $C_1,C_2>0$   is due to Theorem 11.1 in \citet{Davydov:aa} applied to $\sup_{\theta\in\Theta}|\mathbb H_{P,j}(\theta)|$ and $\sup_{\theta\in\Theta}|\mathbb G_{P,j}(\theta)|$ respectively.
Then, for sufficiently large $n$,
\begin{align}
	1-\delta&\le P\Big(	\sqrt n\sup_{\theta\in\Theta}\Big|\frac{n^{-1}\sum_{i=1}^n m_{j}(X_i,\theta)^2}{\sigma_{P,j}^2(\theta)}-\frac{E_P[m_j(X,\theta)^2]}{\sigma_{P,j}^2(\theta)}\Big|\le C_1,\sqrt n\sup_{\theta\in\Theta}\Big|\frac{\bar m_{n,j}(\theta)-E_P[m_j(X,\theta)]}{\sigma_{P,j}(\theta)}\Big|\le C_2\Big)\notag\\
	&\le P\Big(\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}^2(\theta)}{\sigma_{P,j}^2(\theta)}-1\Big|\le C/\sqrt n\Big), \label{eq:ec14}
\end{align}
uniformly in $P\in\mathcal P.$ 

Next, note that, for $x>0$ and $0<\eta<1$, $|x^2-1|\le \eta$ implies $|x-1|\le 1-(1-\eta)^{1/2}\le\eta$, and hence by \eqref{eq:ec14}, for sufficiently large $n$,
\begin{align}
	1-\delta\le  P\Big(\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}(\theta)}{\sigma_{P,j}(\theta)}-1\Big|\le C/\sqrt n\Big),\label{eq:ec15}
\end{align} 
uniformly in $P\in\mathcal P.$ 
Finally, note again that $|\hat\sigma_{n,j}(\theta)/\sigma_{P,j}(\theta)-1|\le \epsilon$ implies $\hat\sigma_{n,j}(\theta)>0$, and
by the local Lipshitz continuity of $x\mapsto 1/x$ on a neighborhood around 1, there is a constant $C'$ such that
\begin{align}
P\Big(\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|\le C'/\sqrt n\Big)	\ge 1-\delta,\label{eq:ec16}
\end{align}
uniformly in $P\in\mathcal P$ for all $n$ sufficiently large.
This establishes the first claim of the lemma.	

(ii) First, consider
\begin{align}
\frac{\hat\sigma^2_{n,j}(\theta)}{\sigma^2_{P,j}(\theta)}=n^{-1}\sum_{i=1}^n\left(\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\right)^2-\left(n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\right)^2.\label{eq:etaLip1}
\end{align}
We claim that this function is Lipschitz with probability approaching 1. To see this, note that, for any $\theta,\theta'\in\Theta$,
\begin{align}
&~ \Bigg|n^{-1}\sum_{i=1}^n\Bigg(\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Bigg)^2 -n^{-1}\sum_{i=1}^n\Bigg(\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg)^2\Bigg|\notag\\
=&~\Bigg|n^{-1}\sum_{i=1}^n \Bigg(\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}+\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg)\Bigg(\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}-\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg)\Bigg|	\notag\\
\le&~ n^{-1}\sum_{i=1}^n 2\sup_{\theta\in\Theta}\Big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Big|\bar M(X_i)\|\theta-\theta'\|.\label{eq:etaLip2}
\end{align}
Define $B_n\equiv n^{-1}\sum_{i=1}^n 2\sup_{\theta\in\Theta}\Big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Big|\bar M(X_i)$. By Markov and Cauchy-Schwarz inequalities,
\begin{align}
	P(B_n>C)\le \frac{E[B_n]}{C}\le\frac{2E_P\left[\sup_{\theta\in\Theta}\Big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Big|^2 \right]^{1/2}E_P\Big[\bar M(X_i)^2 \Big]^{1/2}}{C} \le \frac{2M}{C},\label{eq:etaLip3}
\end{align}
where the third inequality is due to Assumptions \ref{as:momP_AS} (iv) and the assumption on $\bar M$. Hence, for any $\eta>0$, one may find $C>0$ such that $\sup_{P\in\mathcal P}P(B_n>C)<\eta$ for all $n$.

Similarly, for any $\theta,\theta'\in\Theta$,
\begin{align}
&~\Bigg|\Bigg(n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Bigg)^2-\Bigg(n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg)^2	\Bigg|\notag\\
=&~\Bigg|n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}+n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg|\Bigg|n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}-n^{-1}\sum_{i=1}^n\frac{m(X_i,\theta')}{\sigma_{P,j}(\theta')}\Bigg|\notag\\
\le&~ n^{-1}\sum_{i=1}^n 2\sup_{\theta\in\Theta}\Bigg|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Bigg|n^{-1}\sum_{i=1}^n\bar M(X_i)\|\theta-\theta'\|.\label{eq:etaLip4}
\end{align}
Define $\tilde B_n\equiv n^{-1}\sum_{i=1}^n 2\sup_{\theta\in\Theta}\Big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Big|n^{-1}\sum_{i=1}^n\bar M(X_i)$. By Markov, Cauchy-Schwarz, and Jensen's inequalities,
\begin{multline}
	P(\tilde B_n>C)\le \frac{E[\tilde B_n]}{C}\le \frac{2E_P\Big[\Big(n^{-1}\sum\sup_{\theta\in\Theta}\Big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\Big|\Big)^2\Big]^{1/2}E_P\Big[\Big(n^{-1}\sum\bar M(X_i)\Big)^2\Big]^{1/2}}{C} \\
\le \frac{2E_P\Big[\sup_{\theta\in\Theta}\big|\frac{m(X_i,\theta)}{\sigma_{P,j}(\theta)}\big|^2\Big]^{1/2}E_P[\bar M(X_i)^2]^{1/2}}{C}	\le \frac{2M}{C},\label{eq:etaLip5}
\end{multline}
where the last inequality is due to Assumptions \ref{as:momP_AS} (iv) and the assumption on $\bar M$.  Hence, for any $\eta>0$, one may find $C>0$ such that $\sup_{P\in\mathcal P}P(\tilde B_n>C)<\eta$ for all $n$.

Finally, let $g(y)\equiv y^{-1/2}-1$ and note that $|g(y)-g(y')|\le \frac{1}{2}\sup_{\bar y\in (1-\epsilon,1+\epsilon)}|\bar y|^{-3/2}|y-y'|$ on $(1-\epsilon,1+\epsilon).$ As shown in \eqref{eq:ec15}, $\hat\sigma^2_{n,j}(\theta)/\sigma^2_{P,j}(\theta)$ converges to 1 in probability, and $g$ is locally Lipschitz on a neighborhood of 1. Combining this with 
\eqref{eq:etaLip1}-\eqref{eq:etaLip5} yields the desired result.

\begin{align}
	1-\delta&\le P\Big(	\sqrt n\sup_{\theta\in\Theta}\Big|\frac{n^{-1}\sum_{i=1}^n m_{j}(X_i,\theta)^2}{\sigma_{P,j}^2(\theta)}-\frac{E_P[m_j(X,\theta)^2]}{\sigma_{P,j}^2(\theta)}\Big|\le C_1,\sqrt n\sup_{\theta\in\Theta}\Big|\frac{\bar m_{n,j}(\theta)-E_P[m_j(X,\theta)]}{\sigma_{P,j}(\theta)}\Big|\le C_2\Big)\notag\\
	&\le P\Big(\sup_{\theta\in\Theta}\Big|\frac{\hat\sigma_{n,j}^2(\theta)}{\sigma_{P,j}^2(\theta)}-1\Big|\le C/\sqrt n\Big), \label{eq:ec14}
\end{align}

\label{lem:correl_Lip}
Suppose Assumption  \ref{as:momP_AS} holds.
Suppose further that $|\sigma_{P,j}(\theta)^{-1}m_j(x,\theta)-\sigma_{P,j}(\theta')^{-1}m_j(x,\theta')|\le \bar M(x)\|\theta-\theta'\|$ with $E_P[\bar M(X)^{2}]<M$  for all $\theta,\theta'\in\Theta$, $x\in\mathcal X$, $j=1,\cdots,J$, and $P\in\mathcal P$.

Then, 	
\begin{align}
\sup_{P\in\mathcal P}\|Q_P(\theta_1,\tilde\theta_1)-Q_P(\theta_2,\tilde\theta_2)\|\le M\|(\theta_1,\tilde\theta_1)-(\theta_2,\tilde\theta_2)\|,	\label{eq:correl_Lip0}
\end{align}
 for some $M>0$ and for all $\theta_1,\tilde\theta_1,\theta_2,\tilde\theta_2\in \Theta$.

Recall that 
\begin{align}
	[Q_P(\theta_1,\tilde\theta_1)]_{j,k}=E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\frac{m_k(X_i,\tilde \theta_1)}{\sigma_{P,k}(\tilde \theta_1)}\Big]-E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\Big]E_P\Big[\frac{m_k(X_i,\tilde\theta_1)}{\sigma_{P,k}(\tilde \theta_1)}\Big].\label{eq:correl_Lip1}
\end{align}	
For any $\theta_1,\tilde\theta_1,\theta_2,\tilde\theta_2\in \Theta$,
\begin{align}
&~\Big|E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\frac{m_k(X_i,\tilde \theta_1)}{\sigma_{P,k}(\tilde \theta_1)}\Big]-E_P\Big[\frac{m_j(X_i,\theta_2)}{\sigma_{P,j}(\theta_2)}\frac{m_k(X_i,\tilde \theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big]\Big|\notag\\
\le&~ 	\Big|E_P\Big[\Big(\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}-\frac{m_j(X_i,\theta_2)}{\sigma_{P,j}(\theta_2)}\Big)\frac{m_k(X_i,\tilde \theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big]\Big|+\Big|E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\Big(\frac{m_k(X_i,\tilde \theta_1)}{\sigma_{P,k}(\tilde \theta_1)}-\frac{m_k(X_i,\tilde \theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big)\Big]\Big|\notag\\
\le&~ E_P\Big[\sup_{\theta\in\Theta}\Big|\frac{m_k(X_i, \theta)}{\sigma_{P,k}( \theta)}\Big|\bar M(X_i)\Big]\|\theta_1-\theta_2\|+E_P\Big[\sup_{\theta\in\Theta}\Big|\frac{m_j(X_i, \theta)}{\sigma_{P,j}( \theta)}\Big|\bar M(X_i)\Big]\|\tilde\theta_1-\tilde\theta_2\|\notag\\
\le&~ M(\|\theta_1-\theta_2\|+\|\tilde\theta_1-\tilde\theta_2\|),\label{eq:correl_Lip2}
\end{align}
where the last inequality is due to the Cauchy-Schwarz inequality, Assumption \ref{as:momP_AS} (iv), and the assumption on $\bar M$.

Similarly, for any $\theta_1,\tilde\theta_1,\theta_2,\tilde\theta_2\in \Theta$,
\begin{align}
&~	\Big|E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\Big]E_P\Big[\frac{m_k(X_i,\tilde\theta_1)}{\sigma_{P,k}(\tilde \theta_1)}\Big]-E_P\Big[\frac{m_j(X_i,\theta_2)}{\sigma_{P,j}(\theta_2)}\Big]E_P\Big[\frac{m_k(X_i,\tilde\theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big]\Big|\notag\\
\le &~	\Big|E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}-\frac{m_j(X_i,\theta_2)}{\sigma_{P,j}(\theta_2)}\Big]\Big|\Big|E_P\Big[\frac{m_k(X_i,\tilde \theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big]\Big|+\Big|E_P\Big[\frac{m_j(X_i,\theta_1)}{\sigma_{P,j}(\theta_1)}\Big]\Big|\Big|E_P\Big[\frac{m_k(X_i,\tilde \theta_1)}{\sigma_{P,k}(\tilde \theta_1)}-\frac{m_k(X_i,\tilde \theta_2)}{\sigma_{P,k}(\tilde \theta_2)}\Big]\Big|\notag\\
\le &~E_P\Big[\sup_{\theta\in\Theta}\Big|\frac{m_k(X_i, \theta)}{\sigma_{P,k}( \theta)}\Big|\Big]E_P[\bar M(X_i)]\|\theta_1-\theta_2\|+E_P\Big[\sup_{\theta\in\Theta}\Big|\frac{m_j(X_i, \theta)}{\sigma_{P,j}( \theta)}\Big|\Big]E_P[\bar M(X_i)]\|\tilde\theta_1-\tilde\theta_2\|\notag\\
\le &~ M(\|\theta_1-\theta_2\|+\|\tilde\theta_1-\tilde\theta_2\|),\label{eq:correl_Lip3}
\end{align}
where the last inequality is due to the Cauchy-Schwarz inequality, Assumption \ref{as:momP_AS} (iv), and the assumption on $\bar M$.
The conclusion of the lemma then follows from \eqref{eq:correl_Lip1}-\eqref{eq:correl_Lip3}.

\label{lem:bootcons_standardized}
	Let $\mathcal F$ be a class of measurable functions with finite envelope function. Suppose $\mathcal F$ is such that (i) $\mathcal F$ is Donsker and pre-Gaussian uniformly in $P\in\mathcal P$; and (ii) $\sup_{P\in\mathcal P}P^*\|f-Pf\|^2_{\mathcal F}<\infty.$ Then,
\begin{align}
\sup_{h\in BL_1}|E_M[h(\mathfrak G^b_{n})|X^\infty]-E[h(\mathbb G_{P})]|\stackrel{as*}{\to}0,	
\end{align} 
uniformly in $P\in\mathcal P$.

\label{lem:boot_cons}
Suppose Assumptions \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1} hold. Then,
\begin{align}
\sup_{h\in BL_1}|E_M[h(\mathbb G^b_{n})|X^\infty]-E[h(\mathbb G_{P})]|\stackrel{as*}{\to}0,	
\end{align} 
uniformly in $P\in\mathcal P$.

By Assumptions \ref{as:momP_AS} (iv) and \ref{as:bcs1}, Assumptions A.1-A.4 in \citet{BCS14_misp} hold, which in turn implies that, by their Lemma D.1.2, $\mathcal F$ is Donsker and pre-Gaussian uniformly in $P\in\mathcal P$. Further, by Assumption \ref{as:momP_AS} (iv) again, $\sup_{P\in\mathcal P}P^*\|f-Pf\|_{\mathcal F}<\infty$. Hence, by Lemma \ref{lem:bootcons_standardized},
\begin{align}
	\inf_{P\in\mathcal P}P^\infty\Big(\sup_{h\in BL_1}|E_M[h(\mathfrak G^b_{n})|X^\infty]-E[h(\mathbb G_{P})]|^*\to 0\Big)=1.\label{eq:bootcon1}
\end{align}
For later use, we define the following set of sample paths, which has probability 1 uniformly in $P\in\mathcal P$.
\begin{align}
	A\equiv \Big\{x^\infty\in\mathcal X^\infty:\sup_{h\in BL_1}|E_M[h(\mathfrak G^b_{n})|X^\infty=x^\infty]-E[h(\mathbb G_P)]|^*\to 0\Big\}.
\end{align}
Note that $\mathbb G^b_{n,j}$ and $\mathfrak G^b_{n,j}$  are related to each other by the following relationship:
\begin{align}
	\mathbb G^b_{n,j}(\theta)-\mathfrak G^b_{n,j}(\theta)=\mathfrak G^b_{n,j}(\theta)\left(\frac{\sigma_{P,j}(\theta)}{\hat\sigma_{n,j}(\theta)}-1\right)=\mathfrak G^b_{n,j}(\theta)\eta_{n,j}(\theta),~\theta\in\Theta.\label{eq:Gdiff}
\end{align}
By Assumptions \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1}, Lemma \ref{lem:eta_conv} applies. Hence,
\begin{align}
	\inf_{P\in\mathcal P}P^\infty\Big(\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|^*\to 0\Big)=1.\label{eq:etaconv_inboot}
\end{align}
Define the following set of sample paths:
\begin{align}
	B\equiv\Big\{x^\infty\in\mathcal X^\infty:\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|^*\to 0,\forall j=1,\cdots,J\Big\}.
\end{align}
For any $x^\infty\in A\cap B$, it then follows that
\begin{align}
	\sup_{h\in BL_1}\left|E_M[h(\mathbb G^b_{n})|X^\infty=x^\infty]-E[h(\mathbb G_P)]\right|^*\to 0,\label{eq:bootcon2}
\end{align}
due to \eqref{eq:bootcon1} and \eqref{eq:Gdiff}, $h$ being Lipschitz, $\mathfrak G^b_{n,j}$ being bounded (given $x^\infty$), and  $\sup_{\theta\in\Theta}|\eta_{n,j}(\theta)|^*\to 0$ for all $j$. Finally, note that $\inf_{P\in\mathcal P}P^\infty(A\cap B)=1$ due to \eqref{eq:bootcon1}, \eqref{eq:etaconv_inboot}, and De Morgan's law.
This establishes the conclusion of the lemma.

\label{lem:asrep}
Suppose Assumptions \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1} hold. Then, for each $x^\infty\in\mathcal X^\infty$, there exists a sequence $\{\tilde G_{n,x^\infty}\in \ell(\Theta,\mathbb R^J),n\ge 1\}$ and a random element $\tilde G_{P,x^\infty}\in \ell(\Theta,\mathbb R^J)$ defined on some probability space $(\tilde\Omega,\tilde{\mathcal A},\tilde{\mathbf P})$ such that
\begin{align}
	\int h\circ g(x^\infty,m_n)dQ(m_n)&=\int h(\tilde G_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1\\
	\int h(\mathbb G_P(\omega))dP(\omega)&=\int h(\tilde G_{P,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1,
\end{align}
for all $x^\infty\in C$ for some set $C\subset \mathcal X^\infty$ such that $\inf_{P\in\mathcal P}P^\infty(C)=1$ and
\begin{align}
	\inf_{P\in\mathcal P}P^\infty\Big(\big\{x^\infty\in \mathcal X^\infty:\tilde G_{n,x^\infty}\stackrel{\tilde{\mathbf P}-as*}{\to}\tilde G_{P,x^\infty}\big\}\Big)=1.\label{eq:asconv1}
\end{align}

\begin{align}
	\int h\circ g(x^\infty,m_n)dQ(m_n)&=\int h(\tilde G_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1\\
	\int h(\mathbb G_P(\omega))dP(\omega)&=\int h(\tilde G_{P,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1,
\end{align}

Define the following set of sample paths:
\begin{align}
	C\equiv \Big\{x^\infty\in\mathcal X^\infty:\sup_{h\in BL_1}|E_M[h(\mathbb G^b_{n,j})|X^\infty=x^\infty]-E[h(\mathbb G_P)]|^*\to 0\Big\}.
\end{align}
By Lemma \ref{lem:boot_cons}, 	$\inf_{P\in\mathcal P}P^\infty(C)=1$.

For each fixed sample path $x^\infty\in C$, consider the bootstrap empirical process $g(x^\infty,M_n)$ in \eqref{eq:defg}. This is a random element in $\ell^\infty(\Theta,\mathbb R^J)$ with a law governed by $Q$. 
For each $x^\infty\in C$, by Lemma \ref{lem:boot_cons}, 
\begin{align}
\sup_{h\in BL_1}\left|\int h\circ g(x^\infty,m_n)dQ(m_n)-E[h(\mathbb G_P)]\right|^*\to 0.
\end{align}  
Hence, by Theorem 1.10.4 in \citet{Vaart_Wellner2000aBK}, for each $x^\infty\in C$, one may find an almost sure representation $\tilde G_{n,x^\infty}$ of $g(x^\infty,M_n)$ on some probability space $(\tilde\Omega,\tilde{\mathcal A},\tilde{\mathbf P})$ such that
\begin{align}
	\int h\circ g(x^\infty,m_n)dQ(m_n)=\int h(\tilde G_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1.
\end{align}
In particular, the proof of Theorem 1.10.4 in \citet{Vaart_Wellner2000aBK} (see also Addendum 1.10.5) allows us to take $\tilde G_{n,x^\infty}$ to be defined for each $\tilde\omega\in\tilde\Omega$ as
\begin{align}
\tilde G_{n,x^\infty}(\tilde \omega)=g(x^\infty,M_n(\phi_n(\tilde \omega)))	,
\end{align}
for some perfect map $\phi_n:\tilde\Omega\to \mathcal Z$ (see the construction of $\phi_\alpha$ in the middle of page 61 in VW). One may define $\tilde G_{n,x^\infty}$ arbitrarily for any $x^\infty\notin C.$
The almost sure representation $\tilde G_{P,x^\infty}$ of $\mathbb G_{P,j}$ is defined similarly.

By Theorem  1.10.4 in \citet{Vaart_Wellner2000aBK}, Eq. \eqref{eq:bootcon2}, and $\inf_{P\in\mathcal P}P(C)=1$, it follows that
\begin{align}
	\inf_{P\in\mathcal P}P^\infty\Big(\big\{x^\infty\in \mathcal X^\infty:\tilde G_{n,x^\infty}\stackrel{\tilde{\mathbf P}-as*}{\to}\tilde G_{P,x^\infty}\big\}\Big)=1.
\end{align}
This establishes the claim of the lemma.

\begin{align}
	\int h\circ g(x^\infty,m_n)dQ(m_n)=\int h(\tilde G_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1.
\end{align}

\label{cor:asrep}
Suppose Assumptions \ref{as:momP_AS}, \ref{as:GMS}, and \ref{as:bcs1} hold.  Let $W_n\equiv (\mathbb G^b_n,Y_n)$ be a sequence in $\mathcal W\equiv\ell(\Theta,\mathbb R^J)\times \mathbb R^{d_Y}$  such that $Y_n=\tilde g(X^\infty, M_n)$ for some map $\tilde g:\mathcal X^\infty\times \mathcal Z\to\mathbb R^{d_Y}$ and
\begin{align}
\inf_{P\in \mathcal P} P^\infty\big(\sup_{h\in BL_1}|E_M[h(W_n)|X^\infty=x^\infty]-E[h(W)]|^*\to 0\big)=1,\label{eq:Wn_cons}
\end{align}
where $W=(\mathbb G,Y)$ is a Borel measurable random element in $\mathcal W$.  

Then, for each $x^\infty\in\mathcal X^\infty$, there exists a sequence $\{W^*_{n,x^\infty}\in \mathcal W,n\ge 1\}$ and a  random element $W^*_{x^\infty}\in\mathcal W$ defined on some probability space $(\tilde\Omega,\tilde{\mathcal A},\tilde{\mathbf P})$ such that
\begin{align}
	E_M[h(W_n)|X^\infty=x^\infty]&=\int h(W^*_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1\\
	E[h(W)]&=\int h(W^*_{x^\infty}(\tilde\omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1,
\end{align}
for all $x^\infty\in C$ for some set $C\subset \mathcal X^\infty$ such that $\inf_{P\in\mathcal P}P^\infty(C)=1$, and
\begin{align}
	\inf_{P\in\mathcal P}P^\infty\Big(\big\{x^\infty\in \mathcal X^\infty:W^*_{n,x^\infty}\stackrel{\tilde{\mathbf P}-as*}{\to}\tilde W^*_{x^\infty}\big\}\Big)=1.\label{eq:asconv2}
\end{align}

\begin{align}
	E_M[h(W_n)|X^\infty=x^\infty]&=\int h(W^*_{n,x^\infty}(\tilde \omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1\\
	E[h(W)]&=\int h(W^*_{x^\infty}(\tilde\omega))d\tilde{\mathbf P}^*(\tilde\omega),~\forall h\in BL_1,
\end{align}
